var e=`-- Generated by scripts/gen-sdg.mjs. Do not edit by hand.
-- The 17 Sustainable Development Goals and their 169 targets in NL/FR/EN, as reference
-- data for the UI, the API and AI tools. EN/FR: official UN texts (open-sdg). NL:
-- working translation (nl_working = true) until official Dutch texts are imported.

create table public.sdg_goals (
  n int primary key check (n between 1 and 17),
  short_nl text not null, short_fr text not null, short_en text not null,
  title_nl text not null, title_fr text not null, title_en text not null
);
create table public.sdg_targets (
  code text primary key,
  goal int not null references public.sdg_goals (n),
  sort int not null,
  title_nl text not null, title_fr text not null, title_en text not null,
  nl_working boolean not null default true
);
alter table public.sdg_goals enable row level security;
alter table public.sdg_targets enable row level security;

insert into public.sdg_goals (n, short_nl, short_fr, short_en, title_nl, title_fr, title_en) values
(1, 'Geen armoede', 'Pas de pauvreté', 'No poverty', 'Armoede in al haar vormen overal ter wereld uitbannen', 'Éliminer la pauvreté sous toutes ses formes et partout dans le monde', 'End poverty in all its forms everywhere'),
(2, 'Geen honger', 'Faim "zéro"', 'Zero hunger', 'Honger beëindigen, voedselzekerheid en betere voeding bereiken en duurzame landbouw bevorderen', 'Éliminer la faim, assurer la sécurité alimentaire, améliorer la nutrition et promouvoir l’agriculture durable', 'End hunger, achieve food security and improved nutrition and promote sustainable agriculture'),
(3, 'Goede gezondheid en welzijn', 'Bonne santé et bien-être', 'Good health and well-being', 'Een goede gezondheid verzekeren en het welzijn voor iedereen op alle leeftijden bevorderen', 'Permettre à tous de vivre en bonne santé et promouvoir le bien-être de tous à tout âge', 'Ensure healthy lives and promote well-being for all at all ages'),
(4, 'Kwaliteitsonderwijs', 'Éducation de qualité', 'Quality education', 'Inclusief en rechtvaardig kwaliteitsonderwijs verzekeren en levenslang leren voor iedereen bevorderen', 'Assurer à tous une éducation équitable, inclusive et de qualité et des possibilités d’apprentissage    tout au long de la vie', 'Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all'),
(5, 'Gendergelijkheid', 'Égalité entre les sexes', 'Gender equality', 'Gendergelijkheid bereiken en alle vrouwen en meisjes empoweren', 'Parvenir à l’égalité des sexes et autonomiser toutes les femmes et les filles', 'Achieve gender equality and empower all women and girls'),
(6, 'Schoon water en sanitair', 'Eau propre et assainissement', 'Clean water and sanitation', 'De beschikbaarheid en het duurzaam beheer van water en sanitair voor iedereen verzekeren', 'Garantir l’accès de tous à des services d’alimentation en eau et d’assainissement gérés de façon durable', 'Ensure availability and sustainable management of water and sanitation for all'),
(7, 'Betaalbare en duurzame energie', 'Energies propres et d''un coût abordable', 'Affordable and clean energy', 'Toegang tot betaalbare, betrouwbare, duurzame en moderne energie voor iedereen verzekeren', 'Garantir l’accès de tous à des services énergétiques fiables, durables et modernes, à un coût abordable', 'Ensure access to affordable, reliable, sustainable and modern energy for all'),
(8, 'Waardig werk en economische groei', 'Travaux décent et croissance économique', 'Decent work and economic growth', 'Aanhoudende, inclusieve en duurzame economische groei, volledige en productieve tewerkstelling en waardig werk voor iedereen bevorderen', 'Promouvoir une croissance économique soutenue, partagée et durable, le plein emploi productif et un travail décent pour tous', 'Promote sustained, inclusive and sustainable economic growth, full and productive employment and decent work for all'),
(9, 'Industrie, innovatie en infrastructuur', 'Industrie, innovation et infrastructure', 'Industry, innovation and infrastructure', 'Veerkrachtige infrastructuur bouwen, inclusieve en duurzame industrialisering bevorderen en innovatie stimuleren', 'Bâtir une infrastructure résiliente, promouvoir une industrialisation durable qui profite à tous et encourager l’innovation', 'Build resilient infrastructure, promote inclusive and sustainable industrialization and foster innovation'),
(10, 'Ongelijkheid verminderen', 'Inégalités réduites', 'Reduced inequalities', 'Ongelijkheid in en tussen landen verminderen', 'Réduire les inégalités dans les pays et d’un pays à l’autre', 'Reduce inequality within and among countries'),
(11, 'Duurzame steden en gemeenschappen', 'Villes et communautés durables', 'Sustainable cities and communities', 'Steden en menselijke nederzettingen inclusief, veilig, veerkrachtig en duurzaam maken', 'Faire en sorte que les villes et les établissements humains soient ouverts à tous, sûrs, résilients et durables', 'Make cities and human settlements inclusive, safe, resilient and sustainable'),
(12, 'Verantwoorde consumptie en productie', 'Consommation et production responsables', 'Responsible consumption and production', 'Duurzame consumptie- en productiepatronen verzekeren', 'Établir des modes de consommation et de production durables', 'Ensure sustainable consumption and production patterns'),
(13, 'Klimaatactie', 'Mesures relatives à la lutte contre les changements climatiques', 'Climate action', 'Dringend actie ondernemen om klimaatverandering en de gevolgen ervan te bestrijden', 'Prendre d’urgence des mesures pour lutter contre les changements climatiques et leurs répercussions', 'Take urgent action to combat climate change and its impacts'),
(14, 'Leven in het water', 'Vie aquatique', 'Life below water', 'De oceanen, zeeën en mariene hulpbronnen behouden en duurzaam gebruiken voor duurzame ontwikkeling', 'Conserver et exploiter de manière durable les océans, les mers et les ressources marines aux fins du développement durable', 'Conserve and sustainably use the oceans, seas and marine resources for sustainable development'),
(15, 'Leven op het land', 'Vie terrestre', 'Life on land', 'Landecosystemen beschermen, herstellen en duurzaam gebruiken, bossen duurzaam beheren, woestijnvorming bestrijden, bodemdegradatie stoppen en terugdraaien en het verlies aan biodiversiteit stoppen', 'Préserver et restaurer les écosystèmes terrestres, en veillant à les exploiter de façon durable, gérer durablement les forêts, lutter contre la désertification, enrayer et inverser le processus de dégradation des terres et mettre fin à l’appauvrissement de la biodiversité', 'Protect, restore and promote sustainable use of terrestrial ecosystems, sustainably manage forests, combat desertification, and halt and reverse land degradation and halt biodiversity loss'),
(16, 'Vrede, justitie en sterke publieke diensten', 'Paix, justice et institutions efficaces', 'Peace, justice and strong institutions', 'Vreedzame en inclusieve samenlevingen bevorderen, toegang tot justitie voor iedereen verzekeren en doeltreffende, verantwoordingsplichtige en inclusieve instellingen op alle niveaus uitbouwen', 'Promouvoir l’avènement de sociétés pacifiques et inclusives aux fins du développement durable, assurer l’accès de tous à la justice et mettre en place, à tous les niveaux, des institutions efficaces, responsables et ouvertes à tous', 'Promote peaceful and inclusive societies for sustainable development, provide access to justice for all and build effective, accountable and inclusive institutions at all levels'),
(17, 'Partnerschap om doelstellingen te bereiken', 'Partenariats pour la réalisation des objectifs', 'Partnerships for the goals', 'De middelen voor de uitvoering versterken en het wereldwijd partnerschap voor duurzame ontwikkeling nieuw leven inblazen', 'Renforcer les moyens de mettre en œuvre le Partenariat mondial pour le développement durable et le revitaliser', 'Strengthen the means of implementation and revitalize the Global Partnership for Sustainable Development');

insert into public.sdg_targets (code, goal, title_nl, title_fr, title_en, sort)
select code, goal, title_nl, title_fr, title_en, row_number() over () from (values
('1.1', 1, 'Tegen 2030 extreme armoede overal ter wereld uitbannen, momenteel gemeten als leven van minder dan 1,25 dollar per dag', 'D’ici à 2030, éliminer complètement l’extrême pauvreté dans le monde entier (s’entend actuellement du fait de vivre avec moins de 1,25 dollar des États‐Unis par jour)', 'By 2030, eradicate extreme poverty for all people everywhere, currently measured as people living on less than $1.25 a day'),
('1.2', 1, 'Tegen 2030 het aandeel mannen, vrouwen en kinderen van alle leeftijden die in armoede leven, in al haar dimensies volgens nationale definities, minstens halveren', 'D’ici à 2030, réduire de moitié au moins la proportion d’hommes, de femmes et d’enfants de tous âges souffrant d’une forme ou l’autre de pauvreté, telle que définie par chaque pays', 'By 2030, reduce at least by half the proportion of men, women and children of all ages living in poverty in all its dimensions according to national definitions'),
('1.3', 1, 'Nationaal passende systemen en maatregelen voor sociale bescherming voor iedereen invoeren, met inbegrip van minimumniveaus, en tegen 2030 een substantiële dekking van armen en kwetsbaren bereiken', 'Mettre en place des systèmes et mesures de protection sociale pour tous, adaptés au contexte national, y compris des socles de protection sociale, et faire en sorte que, d’ici à 2030, une part importante des pauvres et des personnes vulnérables en bénéficient', 'Implement nationally appropriate social protection systems and measures for all, including floors, and by 2030 achieve substantial coverage of the poor and the vulnerable'),
('1.4', 1, 'Tegen 2030 verzekeren dat alle mannen en vrouwen, in het bijzonder armen en kwetsbaren, gelijke rechten hebben op economische middelen en toegang tot basisdiensten, eigendom en zeggenschap over grond en andere eigendommen, erfenis, natuurlijke hulpbronnen, gepaste nieuwe technologie en financiële diensten, met inbegrip van microfinanciering', 'D’ici à 2030, faire en sorte que tous les hommes et les femmes, en particulier les pauvres et les personnes vulnérables, aient les mêmes droits aux ressources économiques et qu’ils aient accès aux services de base, à la propriété foncière, au contrôle des terres et à d’autres formes de propriété, à l’héritage, aux ressources naturelles et à des nouvelles technologies et des services financiers adaptés à leurs besoins, y compris la microfinance', 'By 2030, ensure that all men and women, in particular the poor and the vulnerable, have equal rights to economic resources, as well as access to basic services, ownership and control over land and other forms of property, inheritance, natural resources, appropriate new technology and financial services, including microfinance'),
('1.5', 1, 'Tegen 2030 de veerkracht van armen en mensen in kwetsbare situaties versterken en hun blootstelling en kwetsbaarheid voor klimaatgerelateerde extreme gebeurtenissen en andere economische, sociale en ecologische schokken en rampen verminderen', 'D’ici à 2030, renforcer la résilience des pauvres et des personnes en situation vulnérable et réduire leur exposition aux phénomènes climatiques extrêmes et à d’autres chocs et catastrophes d’ordre économique, social ou environnemental et leur vulnérabilité', 'By 2030, build the resilience of the poor and those in vulnerable situations and reduce their exposure and vulnerability to climate-related extreme events and other economic, social and environmental shocks and disasters'),
('1.a', 1, 'Een aanzienlijke mobilisatie van middelen uit diverse bronnen verzekeren, onder meer via versterkte ontwikkelingssamenwerking, om ontwikkelingslanden, in het bijzonder de minst ontwikkelde landen, voldoende en voorspelbare middelen te bieden om programma''s en beleid uit te voeren die armoede in al haar dimensies beëindigen', 'Garantir une mobilisation importante de ressources provenant de sources multiples, y compris par le renforcement de la coopération pour le développement, afin de doter les pays en développement, en particulier les pays les moins avancés, de moyens adéquats et prévisibles de mettre en œuvre des programmes et politiques visant à mettre fin à la pauvreté sous toutes ses formes', 'Ensure significant mobilization of resources from a variety of sources, including through enhanced development cooperation, in order to provide adequate and predictable means for developing countries, in particular least developed countries, to implement programmes and policies to end poverty in all its dimensions'),
('1.b', 1, 'Degelijke beleidskaders creëren op nationaal, regionaal en internationaal niveau, gebaseerd op ontwikkelingsstrategieën die armen ten goede komen en gendergevoelig zijn, om versnelde investeringen in armoedebestrijding te ondersteunen', 'Mettre en place aux niveaux national, régional et international des cadres d’action viables, fondés sur des stratégies de développement favorables aux pauvres et soucieuses de la problématique hommes-femmes, afin d’accélérer l’investissement dans des mesures d’élimination de la pauvreté', 'Create sound policy frameworks at the national, regional and international levels, based on pro-poor and gender-sensitive development strategies, to support accelerated investment in poverty eradication actions'),
('2.1', 2, 'Tegen 2030 honger beëindigen en de toegang van alle mensen, in het bijzonder armen en mensen in kwetsbare situaties, met inbegrip van zuigelingen, tot veilig, voedzaam en voldoende voedsel het hele jaar door verzekeren', 'D’ici à 2030, éliminer la faim et faire en sorte que chacun, en particulier les pauvres et les personnes en situation vulnérable, y compris les nourrissons, ait accès toute l’année à une alimentation saine, nutritive et suffisante', 'By 2030, end hunger and ensure access by all people, in particular the poor and people in vulnerable situations, including infants, to safe, nutritious and sufficient food all year round'),
('2.2', 2, 'Tegen 2030 alle vormen van ondervoeding beëindigen, onder meer door tegen 2025 de internationaal overeengekomen doelen inzake groeiachterstand en uitmergeling bij kinderen jonger dan 5 te halen, en tegemoetkomen aan de voedingsbehoeften van adolescente meisjes, zwangere en zogende vrouwen en ouderen', 'D’ici à 2030, mettre fin à toutes les formes de malnutrition, y compris en atteignant d’ici à 2025 les objectifs arrêtés à l’échelle internationale relatifs aux retards de croissance et à l’émaciation chez les enfants de moins de 5 ans, et répondre aux besoins nutritionnels des adolescentes, des femmes enceintes ou allaitantes et des personnes âgées', 'By 2030, end all forms of malnutrition, including achieving, by 2025, the internationally agreed targets on stunting and wasting in children under 5 years of age, and address the nutritional needs of adolescent girls, pregnant and lactating women and older persons'),
('2.3', 2, 'Tegen 2030 de landbouwproductiviteit en de inkomens van kleinschalige voedselproducenten verdubbelen, in het bijzonder van vrouwen, inheemse volkeren, familiale landbouwers, veehoeders en vissers, onder meer via zekere en gelijke toegang tot grond, andere productiemiddelen, kennis, financiële diensten, markten en kansen op meerwaarde en werk buiten de landbouw', 'D’ici à 2030, doubler la productivité agricole et les revenus des petits producteurs alimentaires, en particulier des femmes, des autochtones, des exploitants familiaux, des éleveurs et des pêcheurs, y compris en assurant l’égalité d’accès aux terres, aux autres ressources productives et facteurs de production, au savoir, aux services financiers, aux marchés et aux possibilités d’ajout de valeur et d’emplois autres qu’agricoles', 'By 2030, double the agricultural productivity and incomes of small-scale food producers, in particular women, indigenous peoples, family farmers, pastoralists and fishers, including through secure and equal access to land, other productive resources and inputs, knowledge, financial services, markets and opportunities for value addition and non-farm employment'),
('2.4', 2, 'Tegen 2030 duurzame voedselproductiesystemen verzekeren en veerkrachtige landbouwpraktijken invoeren die de productiviteit en productie verhogen, ecosystemen helpen behouden, het aanpassingsvermogen aan klimaatverandering, extreem weer, droogte, overstromingen en andere rampen versterken en de kwaliteit van land en bodem geleidelijk verbeteren', 'D’ici à 2030, assurer la viabilité des systèmes de production alimentaire et mettre en œuvre des pratiques agricoles résilientes qui permettent d’accroître la productivité et la production, contribuent à la préservation des écosystèmes, renforcent la capacité d’adaptation aux changements climatiques, aux phénomènes météorologiques extrêmes, à la sécheresse, aux inondations et à d’autres catastrophes et améliorent progressivement la qualité des terres et des sols', 'By 2030, ensure sustainable food production systems and implement resilient agricultural practices that increase productivity and production, that help maintain ecosystems, that strengthen capacity for adaptation to climate change, extreme weather, drought, flooding and other disasters and that progressively improve land and soil quality'),
('2.5', 2, 'Tegen 2020 de genetische diversiteit van zaden, teeltgewassen, gekweekte en gedomesticeerde dieren en hun verwante wilde soorten behouden, onder meer via goed beheerde en gediversifieerde zaad- en plantenbanken op nationaal, regionaal en internationaal niveau, en de toegang tot en eerlijke en billijke verdeling van de voordelen van genetische hulpbronnen en bijbehorende traditionele kennis bevorderen, zoals internationaal overeengekomen', 'D’ici à 2020, préserver la diversité génétique des semences, des cultures et des animaux d’élevage ou domestiqués et des espèces sauvages apparentées, y compris au moyen de banques de semences et de plantes bien gérées et diversifiées aux niveaux national, régional et international, et favoriser l’accès aux avantages que présentent l’utilisation des ressources génétiques et du savoir traditionnel associé ainsi que le partage juste et équitable de ces avantages, comme convenu à l’échelle internationale', 'By 2020, maintain the genetic diversity of seeds, cultivated plants and farmed and domesticated animals and their related wild species, including through soundly managed and diversified seed and plant banks at the national, regional and international levels, and promote access to and fair and equitable sharing of benefits arising from the utilization of genetic resources and associated traditional knowledge, as internationally agreed'),
('2.a', 2, 'De investeringen verhogen, onder meer via versterkte internationale samenwerking, in landelijke infrastructuur, landbouwonderzoek en -voorlichting, technologieontwikkeling en genenbanken voor planten en vee, om de landbouwproductiecapaciteit in ontwikkelingslanden, in het bijzonder de minst ontwikkelde landen, te versterken', 'Accroître, notamment grâce au renforcement de la coopération internationale, l’investissement dans l’infrastructure rurale, les services de recherche et de vulgarisation agricoles et la mise au point de technologies et de banques de plantes et de gènes d’animaux d’élevage, afin de renforcer les capacités productives agricoles des pays en développement, en particulier des pays les moins avancés', 'Increase investment, including through enhanced international cooperation, in rural infrastructure, agricultural research and extension services, technology development and plant and livestock gene banks in order to enhance agricultural productive capacity in developing countries, in particular least developed countries'),
('2.b', 2, 'Handelsbeperkingen en -verstoringen op de wereldlandbouwmarkten corrigeren en voorkomen, onder meer door de parallelle afschaffing van alle vormen van landbouwexportsubsidies en alle exportmaatregelen met een gelijkwaardig effect, overeenkomstig het mandaat van de Doha-ontwikkelingsronde', 'Corriger et prévenir les restrictions et distorsions entravant le fonctionnement des marchés agricoles mondiaux, y compris par l’élimination parallèle de toutes les formes de subventions aux exportations agricoles et de toutes les mesures à l’exportation ayant un effet équivalent, conformément au mandat du Cycle de négociations de Doha pour le développement', 'Correct and prevent trade restrictions and distortions in world agricultural markets, including through the parallel elimination of all forms of agricultural export subsidies and all export measures with equivalent effect, in accordance with the mandate of the Doha Development Round'),
('2.c', 2, 'Maatregelen nemen om de goede werking van de markten voor voedingsgrondstoffen en hun derivaten te verzekeren en tijdige toegang tot marktinformatie, ook over voedselreserves, te vergemakkelijken, om extreme schommelingen van voedselprijzen te helpen beperken', 'Adopter des mesures visant à assurer le bon fonctionnement des marchés de denrées alimentaires et de produits dérivés et à faciliter l’accès rapide aux informations relatives à ces marchés, y compris le niveau des réserves alimentaires, afin de contribuer à limiter l’extrême volatilité des prix alimentaires', 'Adopt measures to ensure the proper functioning of food commodity markets and their derivatives and facilitate timely access to market information, including on food reserves, in order to help limit extreme food price volatility'),
('3.1', 3, 'Tegen 2030 de wereldwijde moedersterfte terugdringen tot minder dan 70 per 100.000 levendgeborenen', 'D’ici à 2030, faire passer le taux mondial de mortalité maternelle au-dessous de 70 pour 100 000 naissances vivantes', 'By 2030, reduce the global maternal mortality ratio to less than 70 per 100,000 live births'),
('3.2', 3, 'Tegen 2030 een einde maken aan vermijdbare sterfte bij pasgeborenen en kinderen jonger dan 5, waarbij alle landen de neonatale sterfte terugdringen tot hoogstens 12 per 1.000 levendgeborenen en de sterfte onder de 5 jaar tot hoogstens 25 per 1.000 levendgeborenen', 'D’ici à 2030, éliminer les décès évitables de nouveau-nés et d’enfants de moins de 5 ans, tous les pays devant chercher à ramener la mortalité néonatale à 12 pour 1 000 naissances vivantes au plus et la mortalité des enfants de moins de 5 ans à 25 pour 1 000 naissances vivantes au plus', 'By 2030, end preventable deaths of newborns and children under 5 years of age, with all countries aiming to reduce neonatal mortality to at least as low as 12 per 1,000 live births and under‐5 mortality to at least as low as 25 per 1,000 live births'),
('3.3', 3, 'Tegen 2030 een einde maken aan de epidemieën van aids, tuberculose, malaria en verwaarloosde tropische ziekten en hepatitis, door water overgedragen ziekten en andere besmettelijke ziekten bestrijden', 'D’ici à 2030, mettre fin à l’épidémie de sida, à la tuberculose, au paludisme et aux maladies tropicales négligées et combattre l’hépatite, les maladies transmises par l’eau et autres maladies transmissibles', 'By 2030, end the epidemics of AIDS, tuberculosis, malaria and neglected tropical diseases and combat hepatitis, water-borne diseases and other communicable diseases'),
('3.4', 3, 'Tegen 2030 de vroegtijdige sterfte door niet-besmettelijke ziekten met een derde verminderen via preventie en behandeling, en geestelijke gezondheid en welzijn bevorderen', 'D’ici à 2030, réduire d’un tiers, par la prévention et le traitement, le taux de mortalité prématurée due à des maladies non transmissibles et promouvoir la santé mentale et le bien-être', 'By 2030, reduce by one third premature mortality from non-communicable diseases through prevention and treatment and promote mental health and well-being'),
('3.5', 3, 'De preventie en behandeling van middelenmisbruik versterken, met inbegrip van drugsmisbruik en schadelijk alcoholgebruik', 'Renforcer la prévention et le traitement de l’abus de substances psychoactives, notamment de stupéfiants et d’alcool', 'Strengthen the prevention and treatment of substance abuse, including narcotic drug abuse and harmful use of alcohol'),
('3.6', 3, 'Tegen 2020 het aantal doden en gewonden door verkeersongevallen wereldwijd halveren', 'D’ici à 2020, diminuer de moitié à l’échelle mondiale le nombre de décès et de blessures dus à des accidents de la route', 'By 2020, halve the number of global deaths and injuries from road traffic accidents'),
('3.7', 3, 'Tegen 2030 universele toegang verzekeren tot seksuele en reproductieve gezondheidszorg, met inbegrip van gezinsplanning, informatie en onderwijs, en reproductieve gezondheid integreren in nationale strategieën en programma''s', 'D’ici à 2030, assurer l’accès de tous à des services de soins de santé sexuelle et procréative, y compris à des fins de planification familiale, d’information et d’éducation, et veiller à la prise en compte de la santé procréative dans les stratégies et programmes nationaux', 'By 2030, ensure universal access to sexual and reproductive health-care services, including for family planning, information and education, and the integration of reproductive health into national strategies and programmes'),
('3.8', 3, 'Universele gezondheidsdekking bereiken, met inbegrip van bescherming tegen financiële risico''s, toegang tot essentiële zorg van goede kwaliteit en toegang tot veilige, doeltreffende, kwaliteitsvolle en betaalbare essentiële geneesmiddelen en vaccins voor iedereen', 'Faire en sorte que chacun bénéficie d’une couverture sanitaire universelle, comprenant une protection contre les risques financiers et donnant accès à des services de santé essentiels de qualité et à des médicaments et vaccins essentiels sûrs, efficaces, de qualité et d’un coût abordable', 'Achieve universal health coverage, including financial risk protection, access to quality essential health-care services and access to safe, effective, quality and affordable essential medicines and vaccines for all'),
('3.9', 3, 'Tegen 2030 het aantal doden en zieken door gevaarlijke chemicaliën en door lucht-, water- en bodemvervuiling en -verontreiniging aanzienlijk verminderen', 'D’ici à 2030, réduire nettement le nombre de décès et de maladies dus à des substances chimiques dangereuses et à la pollution et à la contamination de l’air, de l’eau et du sol', 'By 2030, substantially reduce the number of deaths and illnesses from hazardous chemicals and air, water and soil pollution and contamination'),
('3.a', 3, 'De uitvoering van het Kaderverdrag van de Wereldgezondheidsorganisatie inzake tabaksontmoediging in alle landen versterken, waar gepast', 'Renforcer dans tous les pays, selon qu’il convient, l’application de la Convention-cadre de l’Organisation mondiale de la Santé pour la lutte antitabac', 'Strengthen the implementation of the World Health Organization Framework Convention on Tobacco Control in all countries, as appropriate'),
('3.b', 3, 'Onderzoek naar en ontwikkeling van vaccins en geneesmiddelen ondersteunen voor besmettelijke en niet-besmettelijke ziekten die vooral ontwikkelingslanden treffen, en toegang bieden tot betaalbare essentiële geneesmiddelen en vaccins, overeenkomstig de Verklaring van Doha over de TRIPS-overeenkomst en volksgezondheid', 'Appuyer la recherche et le développement de vaccins et de médicaments contre les maladies, transmissibles ou non, qui touchent principalement les habitants des pays en développement, donner accès, à un coût abordable, aux médicaments et vaccins essentiels, conformément à la Déclaration de Doha sur l’Accord sur les aspects des droits de propriété intellectuelle qui touchent au commerce (ADPIC) et la santé publique, qui réaffirme le droit qu’ont les pays en développement de tirer pleinement parti des dispositions de cet accord qui ménagent une flexibilité lorsqu’il s’agit de protéger la santé publique et, en particulier, d’assurer l’accès universel aux médicaments', 'Support the research and development of vaccines and medicines for the communicable and non‐communicable diseases that primarily affect developing countries, provide access to affordable essential medicines and vaccines, in accordance with the Doha Declaration on the TRIPS Agreement and Public Health, which affirms the right of developing countries to use to the full the provisions in the Agreement on Trade-Related Aspects of Intellectual Property Rights regarding flexibilities to protect public health, and, in particular, provide access to medicines for all'),
('3.c', 3, 'De financiering van gezondheidszorg en de rekrutering, ontwikkeling, opleiding en het behoud van zorgpersoneel in ontwikkelingslanden aanzienlijk verhogen, vooral in de minst ontwikkelde landen en kleine eilandstaten in ontwikkeling', 'Accroître considérablement le budget de la santé et le recrutement, le perfectionnement, la formation et le maintien en poste du personnel de santé dans les pays en développement, notamment dans les pays les moins avancés et les petits États insulaires en développement', 'Substantially increase health financing and the recruitment, development, training and retention of the health workforce in developing countries, especially in least developed countries and small island developing States'),
('3.d', 3, 'De capaciteit van alle landen, in het bijzonder ontwikkelingslanden, versterken voor vroegtijdige waarschuwing, risicobeperking en beheer van nationale en wereldwijde gezondheidsrisico''s', 'Renforcer les moyens dont disposent tous les pays, en particulier les pays en développement, en matière d’alerte rapide, de réduction des risques et de gestion des risques sanitaires nationaux et mondiaux', 'Strengthen the capacity of all countries, in particular developing countries, for early warning, risk reduction and management of national and global health risks'),
('4.1', 4, 'Tegen 2030 verzekeren dat alle meisjes en jongens gratis, gelijkwaardig en kwaliteitsvol lager en secundair onderwijs afmaken dat tot relevante en doeltreffende leerresultaten leidt', 'D’ici à 2030, faire en sorte que toutes les filles et tous les garçons suivent, sur un pied d’égalité, un cycle complet d’enseignement primaire et secondaire gratuit et de qualité, les dotant d’acquis véritablement utiles', 'By 2030, ensure that all girls and boys complete free, equitable and quality primary and secondary education leading to relevant and effective learning outcomes'),
('4.2', 4, 'Tegen 2030 verzekeren dat alle meisjes en jongens toegang hebben tot kwaliteitsvolle ontwikkeling, opvang en voorschools onderwijs in de vroege kindertijd, zodat ze klaar zijn voor het lager onderwijs', 'D’ici à 2030, faire en sorte que toutes les filles et tous les garçons aient accès à des services de développement et de prise en charge de la petite enfance et à une éducation préscolaire de qualité qui les préparent à suivre un enseignement primaire', 'By 2030, ensure that all girls and boys have access to quality early childhood development, care and pre‐primary education so that they are ready for primary education'),
('4.3', 4, 'Tegen 2030 gelijke toegang verzekeren voor alle vrouwen en mannen tot betaalbaar en kwaliteitsvol technisch, beroeps- en hoger onderwijs, met inbegrip van universiteit', 'D’ici à 2030, faire en sorte que toutes les femmes et tous les hommes aient accès dans des conditions d’égalité à un enseignement technique, professionnel ou tertiaire, y compris universitaire, de qualité et d’un coût abordable', 'By 2030, ensure equal access for all women and men to affordable and quality technical, vocational and tertiary education, including university'),
('4.4', 4, 'Tegen 2030 het aantal jongeren en volwassenen met relevante vaardigheden, waaronder technische en beroepsvaardigheden, voor tewerkstelling, waardige banen en ondernemerschap aanzienlijk verhogen', 'D’ici à 2030, augmenter nettement le nombre de jeunes et d’adultes disposant des compétences, notamment techniques et professionnelles, nécessaires à l’emploi, à l’obtention d’un travail décent et à l’entrepreneuriat', 'By 2030, substantially increase the number of youth and adults who have relevant skills, including technical and vocational skills, for employment, decent jobs and entrepreneurship'),
('4.5', 4, 'Tegen 2030 genderverschillen in het onderwijs wegwerken en gelijke toegang verzekeren tot alle niveaus van onderwijs en beroepsopleiding voor kwetsbaren, onder wie personen met een handicap, inheemse volkeren en kinderen in kwetsbare situaties', 'D’ici à 2030, éliminer les inégalités entre les sexes dans le domaine de l’éducation et assurer l’égalité d’accès des personnes vulnérables, y compris les personnes handicapées, les autochtones et les enfants en situation vulnérable, à tous les niveaux d’enseignement et de formation professionnelle', 'By 2030, eliminate gender disparities in education and ensure equal access to all levels of education and vocational training for the vulnerable, including persons with disabilities, indigenous peoples and children in vulnerable situations'),
('4.6', 4, 'Tegen 2030 verzekeren dat alle jongeren en een groot deel van de volwassenen, mannen en vrouwen, kunnen lezen, schrijven en rekenen', 'D’ici à 2030, faire en sorte que tous les jeunes et une proportion considérable d’adultes, hommes et femmes, sachent lire, écrire et compter', 'By 2030, ensure that all youth and a substantial proportion of adults, both men and women, achieve literacy and numeracy'),
('4.7', 4, 'Tegen 2030 verzekeren dat alle lerenden de kennis en vaardigheden verwerven om duurzame ontwikkeling te bevorderen, onder meer via onderwijs over duurzame ontwikkeling en duurzame levensstijlen, mensenrechten, gendergelijkheid, een cultuur van vrede en geweldloosheid, wereldburgerschap en waardering voor culturele diversiteit en de bijdrage van cultuur aan duurzame ontwikkeling', 'D’ici à 2030, faire en sorte que tous les élèves acquièrent les connaissances et compétences nécessaires pour promouvoir le développement durable, notamment par l’éducation en faveur du développement et de modes de vie durables, des droits de l’homme, de l’égalité des sexes, de la promotion d’une culture de paix et de non-violence, de la citoyenneté mondiale et de l’appréciation de la diversité culturelle et de la contribution de la culture au développement durable', 'By 2030, ensure that all learners acquire the knowledge and skills needed to promote sustainable development, including, among others, through education for sustainable development and sustainable lifestyles, human rights, gender equality, promotion of a culture of peace and non-violence, global citizenship and appreciation of cultural diversity and of culture’s contribution to sustainable development'),
('4.a', 4, 'Onderwijsvoorzieningen bouwen en verbeteren die rekening houden met kinderen, handicap en gender en die veilige, geweldloze, inclusieve en doeltreffende leeromgevingen voor iedereen bieden', 'Construire des établissements scolaires qui soient adaptés aux enfants, aux personnes handicapées et aux deux sexes ou adapter les établissements existants à cette fin et fournir à tous un cadre d’apprentissage sûr, non violent, inclusif et efficace', 'Build and upgrade education facilities that are child, disability and gender sensitive and provide safe, non-violent, inclusive and effective learning environments for all'),
('4.b', 4, 'Tegen 2020 het aantal beurzen voor studenten uit ontwikkelingslanden, in het bijzonder de minst ontwikkelde landen, kleine eilandstaten in ontwikkeling en Afrikaanse landen, voor hoger onderwijs, beroepsopleiding en ICT-, technische, ingenieurs- en wetenschappelijke programma''s wereldwijd aanzienlijk uitbreiden', 'D’ici à 2020, augmenter nettement à l’échelle mondiale le nombre de bourses d’études offertes à des étudiants des pays en développement, en particulier des pays les moins avancés, des petits États insulaires en développement et des pays d’Afrique, pour leur permettre de suivre des études supérieures, y compris une formation professionnelle, des cursus informatiques, techniques et scientifiques et des études d’ingénieur, dans des pays développés et d’autres pays en développement', 'By 2020, substantially expand globally the number of scholarships available to developing countries, in particular least developed countries, small island developing States and African countries, for enrolment in higher education, including vocational training and information and communications technology, technical, engineering and scientific programmes, in developed countries and other developing countries'),
('4.c', 4, 'Tegen 2030 het aanbod van gekwalificeerde leerkrachten aanzienlijk verhogen, onder meer via internationale samenwerking voor lerarenopleiding in ontwikkelingslanden, vooral in de minst ontwikkelde landen en kleine eilandstaten in ontwikkeling', 'D’ici à 2030, accroître nettement le nombre d’enseignants qualifiés, notamment au moyen de la coopération internationale pour la formation d’enseignants dans les pays en développement, surtout dans les pays les moins avancés et les petits États insulaires en développement', 'By 2030, substantially increase the supply of qualified teachers, including through international cooperation for teacher training in developing countries, especially least developed countries and small island developing States'),
('5.1', 5, 'Een einde maken aan alle vormen van discriminatie van alle vrouwen en meisjes, overal', 'Mettre fin, partout dans le monde, à toutes les formes de discrimination à l’égard des femmes et des filles', 'End all forms of discrimination against all women and girls everywhere'),
('5.2', 5, 'Alle vormen van geweld tegen alle vrouwen en meisjes in de publieke en private sfeer uitbannen, met inbegrip van mensenhandel en seksuele en andere vormen van uitbuiting', 'Éliminer de la vie publique et de la vie privée toutes les formes de violence faite aux femmes et aux filles, y compris la traite et l’exploitation sexuelle et d’autres types d’exploitation', 'Eliminate all forms of violence against all women and girls in the public and private spheres, including trafficking and sexual and other types of exploitation'),
('5.3', 5, 'Alle schadelijke praktijken uitbannen, zoals kindhuwelijken, vroege en gedwongen huwelijken en genitale verminking bij vrouwen', 'Éliminer toutes les pratiques préjudiciables, telles que le mariage des enfants, le mariage précoce ou forcé et la mutilation génitale féminine', 'Eliminate all harmful practices, such as child, early and forced marriage and female genital mutilation'),
('5.4', 5, 'Onbetaald zorg- en huishoudelijk werk erkennen en waarderen via openbare diensten, infrastructuur en sociaal beschermingsbeleid en via gedeelde verantwoordelijkheid binnen huishouden en gezin, zoals nationaal gepast', 'Prendre en compte et valoriser les soins et travaux domestiques non rémunérés, par la mise en place de services publics, d’infrastructures et de politiques de protection sociale et par la promotion du partage des responsabilités dans le ménage et la famille, en fonction du contexte national', 'Recognize and value unpaid care and domestic work through the provision of public services, infrastructure and social protection policies and the promotion of shared responsibility within the household and the family as nationally appropriate'),
('5.5', 5, 'De volledige en doeltreffende deelname van vrouwen en gelijke kansen op leiderschap op alle besluitvormingsniveaus in het politieke, economische en openbare leven verzekeren', 'Veiller à ce que les femmes participent pleinement et effectivement aux fonctions de direction à tous les niveaux de décision, dans la vie politique, économique et publique, et y accèdent sur un pied d’égalité', 'Ensure women’s full and effective participation and equal opportunities for leadership at all levels of decision-making in political, economic and public life'),
('5.6', 5, 'Universele toegang verzekeren tot seksuele en reproductieve gezondheid en reproductieve rechten, zoals overeengekomen in het Actieprogramma van de Internationale Conferentie over Bevolking en Ontwikkeling, het Actieplatform van Beijing en de slotdocumenten van hun evaluatieconferenties', 'Assurer l’accès de tous aux soins de santé sexuelle et procréative et faire en sorte que chacun puisse exercer ses droits en matière de procréation, ainsi qu’il a été décidé dans le Programme d’action de la Conférence internationale sur la population et le développement et le Programme d’action de Beijing et les documents finals des conférences d’examen qui ont suivi', 'Ensure universal access to sexual and reproductive health and reproductive rights as agreed in accordance with the Programme of Action of the International Conference on Population and Development and the Beijing Platform for Action and the outcome documents of their review conferences'),
('5.a', 5, 'Hervormingen doorvoeren om vrouwen gelijke rechten te geven op economische middelen en toegang tot eigendom en zeggenschap over grond en andere eigendommen, financiële diensten, erfenis en natuurlijke hulpbronnen, overeenkomstig de nationale wetgeving', 'Entreprendre des réformes visant à donner aux femmes les mêmes droits aux ressources économiques, ainsi que l’accès à la propriété et au contrôle des terres et d’autres formes de propriété, aux services financiers, à l’héritage et aux ressources naturelles, dans le respect de la législation interne', 'Undertake reforms to give women equal rights to economic resources, as well as access to ownership and control over land and other forms of property, financial services, inheritance and natural resources, in accordance with national laws'),
('5.b', 5, 'Het gebruik van ondersteunende technologie, in het bijzonder ICT, verbeteren om de empowerment van vrouwen te bevorderen', 'Renforcer l’utilisation des technologies clefs, en particulier de l’informatique et des communications, pour favoriser l’autonomisation des femmes', 'Enhance the use of enabling technology, in particular information and communications technology, to promote the empowerment of women'),
('5.c', 5, 'Degelijk beleid en afdwingbare wetgeving aannemen en versterken om gendergelijkheid en de empowerment van alle vrouwen en meisjes op alle niveaus te bevorderen', 'Adopter des politiques bien conçues et des dispositions législatives applicables en faveur de la promotion de l’égalité des sexes et de l’autonomisation de toutes les femmes et de toutes les filles à tous les niveaux et renforcer celles qui existent', 'Adopt and strengthen sound policies and enforceable legislation for the promotion of gender equality and the empowerment of all women and girls at all levels'),
('6.1', 6, 'Tegen 2030 universele en billijke toegang tot veilig en betaalbaar drinkwater voor iedereen bereiken', 'D’ici à 2030, assurer l’accès universel et équitable à l’eau potable, à un coût abordable', 'By 2030, achieve universal and equitable access to safe and affordable drinking water for all'),
('6.2', 6, 'Tegen 2030 toegang tot passende en billijke sanitaire voorzieningen en hygiëne voor iedereen bereiken en een einde maken aan openluchtdefecatie, met bijzondere aandacht voor de noden van vrouwen en meisjes en mensen in kwetsbare situaties', 'D’ici à 2030, assurer l’accès de tous, dans des conditions équitables, à des services d’assainissement et d’hygiène adéquats et mettre fin à la défécation en plein air, en accordant une attention particulière aux besoins des femmes et des filles et des personnes en situation vulnérable', 'By 2030, achieve access to adequate and equitable sanitation and hygiene for all and end open defecation, paying special attention to the needs of women and girls and those in vulnerable situations'),
('6.3', 6, 'Tegen 2030 de waterkwaliteit verbeteren door vervuiling te verminderen, lozingen te stoppen en de uitstoot van gevaarlijke chemicaliën en stoffen te minimaliseren, het aandeel onbehandeld afvalwater te halveren en recyclage en veilig hergebruik wereldwijd aanzienlijk te verhogen', 'D’ici à 2030, améliorer la qualité de l’eau en réduisant la pollution, en éliminant l’immersion de déchets et en réduisant au minimum les émissions de produits chimiques et de matières dangereuses, en diminuant de moitié la proportion d’eaux usées non traitées et en augmentant nettement à l’échelle mondiale le recyclage et la réutilisation sans danger de l’eau', 'By 2030, improve water quality by reducing pollution, eliminating dumping and minimizing release of hazardous chemicals and materials, halving the proportion of untreated wastewater and substantially increasing recycling and safe reuse globally'),
('6.4', 6, 'Tegen 2030 de efficiëntie van het watergebruik in alle sectoren aanzienlijk verhogen en een duurzame onttrekking en levering van zoetwater verzekeren om waterschaarste aan te pakken en het aantal mensen dat eronder lijdt aanzienlijk te verminderen', 'D’ici à 2030, faire en sorte que les ressources en eau soient utilisées beaucoup plus efficacement dans tous les secteurs et garantir la viabilité des prélèvements et de l’approvisionnement en eau douce afin de remédier à la pénurie d’eau et de réduire nettement le nombre de personnes qui manquent d’eau', 'By 2030, substantially increase water-use efficiency across all sectors and ensure sustainable withdrawals and supply of freshwater to address water scarcity and substantially reduce the number of people suffering from water scarcity'),
('6.5', 6, 'Tegen 2030 geïntegreerd beheer van watervoorraden op alle niveaus invoeren, met inbegrip van grensoverschrijdende samenwerking waar gepast', 'D’ici à 2030, assurer la gestion intégrée des ressources en eau à tous les niveaux, y compris au moyen de la coopération transfrontière selon qu’il convient', 'By 2030, implement integrated water resources management at all levels, including through transboundary cooperation as appropriate'),
('6.6', 6, 'Tegen 2020 watergerelateerde ecosystemen beschermen en herstellen, met inbegrip van bergen, bossen, wetlands, rivieren, watervoerende lagen en meren', 'D’ici à 2020, protéger et restaurer les écosystèmes liés à l’eau, notamment les montagnes, les forêts, les zones humides, les rivières, les aquifères et les lacs', 'By 2020, protect and restore water-related ecosystems, including mountains, forests, wetlands, rivers, aquifers and lakes'),
('6.a', 6, 'Tegen 2030 de internationale samenwerking en de ondersteuning van capaciteitsopbouw in ontwikkelingslanden uitbreiden voor activiteiten en programma''s rond water en sanitair, waaronder wateropvang, ontzilting, waterefficiëntie, afvalwaterbehandeling en technologieën voor recyclage en hergebruik', 'D’ici à 2030, développer la coopération internationale et l’appui au renforcement des capacités des pays en développement en ce qui concerne les activités et programmes relatifs à l’eau et à l’assainissement, y compris la collecte, la désalinisation et l’utilisation rationnelle de l’eau, le traitement des eaux usées, le recyclage et les techniques de réutilisation', 'By 2030, expand international cooperation and capacity-building support to developing countries in water- and sanitation-related activities and programmes, including water harvesting, desalination, water efficiency, wastewater treatment, recycling and reuse technologies'),
('6.b', 6, 'De deelname van lokale gemeenschappen aan de verbetering van het water- en sanitairbeheer ondersteunen en versterken', 'Appuyer et renforcer la participation de la population locale à l’amélioration de la gestion de l’eau et de l’assainissement', 'Support and strengthen the participation of local communities in improving water and sanitation management'),
('7.1', 7, 'Tegen 2030 universele toegang tot betaalbare, betrouwbare en moderne energiediensten verzekeren', 'D’ici à 2030, garantir l’accès de tous à des services énergétiques fiables et modernes, à un coût abordable', 'By 2030, ensure universal access to affordable, reliable and modern energy services'),
('7.2', 7, 'Tegen 2030 het aandeel hernieuwbare energie in de wereldwijde energiemix aanzienlijk verhogen', 'D’ici à 2030, accroître nettement la part de l’énergie renouvelable dans le bouquet énergétique mondial', 'By 2030, increase substantially the share of renewable energy in the global energy mix'),
('7.3', 7, 'Tegen 2030 het wereldwijde tempo van verbetering van de energie-efficiëntie verdubbelen', 'D’ici à 2030, multiplier par deux le taux mondial d’amélioration de l’efficacité énergétique', 'By 2030, double the global rate of improvement in energy efficiency'),
('7.a', 7, 'Tegen 2030 de internationale samenwerking versterken om de toegang tot onderzoek en technologie voor schone energie te vergemakkelijken, met inbegrip van hernieuwbare energie, energie-efficiëntie en geavanceerdere en schonere fossiele technologie, en investeringen in energie-infrastructuur en schone-energietechnologie bevorderen', 'D’ici à 2030, renforcer la coopération internationale en vue de faciliter l’accès aux sciences et technologies de l’énergie propre, notamment les énergies renouvelables, l’efficacité énergétique et les nouvelles technologies de combustion propre des combustibles fossiles, et encourager l’investissement dans l’infrastructure énergétique et les technologies propres dans le domaine de l’énergie', 'By 2030, enhance international cooperation to facilitate access to clean energy research and technology, including renewable energy, energy efficiency and advanced and cleaner fossil-fuel technology, and promote investment in energy infrastructure and clean energy technology'),
('7.b', 7, 'Tegen 2030 de infrastructuur uitbreiden en de technologie verbeteren om moderne en duurzame energiediensten te leveren aan iedereen in ontwikkelingslanden, in het bijzonder de minst ontwikkelde landen, kleine eilandstaten in ontwikkeling en ingesloten ontwikkelingslanden, overeenkomstig hun ondersteuningsprogramma''s', 'D’ici à 2030, développer l’infrastructure et améliorer la technologie afin de fournir des services énergétiques modernes et durables à tous les habitants des pays en développement, en particulier des pays les moins avancés, des petits États insulaires en développement et des pays en développement sans littoral, dans le respect des programmes d’aide qui les concernent', 'By 2030, expand infrastructure and upgrade technology for supplying modern and sustainable energy services for all in developing countries, in particular least developed countries, small island developing States and landlocked developing countries, in accordance with their respective programmes of support'),
('8.1', 8, 'Economische groei per inwoner in stand houden volgens de nationale omstandigheden en, in het bijzonder, een groei van het bruto binnenlands product van minstens 7 procent per jaar in de minst ontwikkelde landen', 'Maintenir un taux de croissance économique par habitant adapté au contexte national et, en particulier, un taux de croissance annuelle du produit intérieur brut d’au moins 7 pour cent dans les pays les moins avancés', 'Sustain per capita economic growth in accordance with national circumstances and, in particular, at least 7 per cent gross domestic product growth per annum in the least developed countries'),
('8.2', 8, 'Hogere niveaus van economische productiviteit bereiken via diversificatie, technologische vernieuwing en innovatie, onder meer met aandacht voor sectoren met een hoge toegevoegde waarde en arbeidsintensieve sectoren', 'Parvenir à un niveau élevé de productivité économique par la diversification, la modernisation technologique et l’innovation, notamment en mettant l’accent sur les secteurs à forte valeur ajoutée et à forte intensité de main-d’œuvre', 'Achieve higher levels of economic productivity through diversification, technological upgrading and innovation, including through a focus on high-value added and labour-intensive sectors'),
('8.3', 8, 'Ontwikkelingsgericht beleid bevorderen dat productieve activiteiten, het scheppen van waardige banen, ondernemerschap, creativiteit en innovatie ondersteunt, en de formalisering en groei van micro-, kleine en middelgrote ondernemingen aanmoedigen, onder meer via toegang tot financiële diensten', 'Promouvoir des politiques axées sur le développement qui favorisent les activités productives, la création d’emplois décents, l’entrepreneuriat, la créativité et l’innovation et stimulent la croissance des microentreprises et des petites et moyennes entreprises et facilitent leur intégration dans le secteur formel, y compris par l’accès aux services financiers', 'Promote development-oriented policies that support productive activities, decent job creation, entrepreneurship, creativity and innovation, and encourage the formalization and growth of micro-, small- and medium-sized enterprises, including through access to financial services'),
('8.4', 8, 'Tot 2030 de wereldwijde efficiëntie van grondstoffengebruik in consumptie en productie geleidelijk verbeteren en ernaar streven economische groei los te koppelen van milieuschade, overeenkomstig het Tienjarenkader van programma''s voor duurzame consumptie en productie, met ontwikkelde landen voorop', 'Améliorer progressivement, jusqu’en 2030, l’efficacité de l’utilisation des ressources mondiales dans les modes de consommation et de production et s’attacher à dissocier croissance économique et dégradation de l’environnement, comme prévu dans le Cadre décennal de programmation concernant les modes de consommation et de production durables, les pays développés montrant l’exemple en la matière', 'Improve progressively, through 2030, global resource efficiency in consumption and production and endeavour to decouple economic growth from environmental degradation, in accordance with the 10‐Year Framework of Programmes on Sustainable Consumption and Production, with developed countries taking the lead'),
('8.5', 8, 'Tegen 2030 volledige en productieve tewerkstelling en waardig werk bereiken voor alle vrouwen en mannen, met inbegrip van jongeren en personen met een handicap, en gelijk loon voor werk van gelijke waarde', 'D’ici à 2030, parvenir au plein emploi productif et garantir à toutes les femmes et à tous les hommes, y compris les jeunes et les personnes handicapées, un travail décent et un salaire égal pour un travail de valeur égale', 'By 2030, achieve full and productive employment and decent work for all women and men, including for young people and persons with disabilities, and equal pay for work of equal value'),
('8.6', 8, 'Tegen 2020 het aandeel jongeren zonder werk, onderwijs of opleiding aanzienlijk verminderen', 'D’ici à 2020, réduire nettement la proportion de jeunes non scolarisés et sans emploi ni formation', 'By 2020, substantially reduce the proportion of youth not in employment, education or training'),
('8.7', 8, 'Onmiddellijke en doeltreffende maatregelen nemen om dwangarbeid uit te bannen, een einde te maken aan moderne slavernij en mensenhandel en het verbod op en de uitbanning van de ergste vormen van kinderarbeid te verzekeren, met inbegrip van de rekrutering en inzet van kindsoldaten, en tegen 2025 een einde maken aan kinderarbeid in al haar vormen', 'Prendre des mesures immédiates et efficaces pour supprimer le travail forcé, mettre fin à l’esclavage moderne et à la traite d’êtres humains, interdire et éliminer les pires formes de travail des enfants, y compris le recrutement et l’utilisation d’enfants soldats, et, d’ici à 2025, mettre fin au travail des enfants sous toutes ses formes', 'Take immediate and effective measures to eradicate forced labour, end modern slavery and human trafficking and secure the prohibition and elimination of the worst forms of child labour, including recruitment and use of child soldiers, and by 2025 end child labour in all its forms'),
('8.8', 8, 'Arbeidsrechten beschermen en veilige en zekere werkomgevingen bevorderen voor alle werknemers, met inbegrip van migrerende werknemers, in het bijzonder vrouwelijke migranten, en mensen in precaire tewerkstelling', 'Défendre les droits des travailleurs, promouvoir la sécurité sur le lieu de travail et assurer la protection de tous les travailleurs, y compris les migrants, en particulier les femmes, et ceux qui ont un emploi précaire', 'Protect labour rights and promote safe and secure working environments for all workers, including migrant workers, in particular women migrants, and those in precarious employment'),
('8.9', 8, 'Tegen 2030 beleid uitwerken en uitvoeren om duurzaam toerisme te bevorderen dat banen schept en de lokale cultuur en producten promoot', 'D’ici à 2030, élaborer et mettre en œuvre des politiques visant à développer un tourisme durable qui crée des emplois et met en valeur la culture et les produits locaux', 'By 2030, devise and implement policies to promote sustainable tourism that creates jobs and promotes local culture and products'),
('8.10', 8, 'De capaciteit van binnenlandse financiële instellingen versterken om de toegang tot bank-, verzekerings- en financiële diensten voor iedereen aan te moedigen en uit te breiden', 'Renforcer la capacité des institutions financières nationales de favoriser et généraliser l’accès de tous aux services bancaires et financiers et aux services d’assurance', 'Strengthen the capacity of domestic financial institutions to encourage and expand access to banking, insurance and financial services for all'),
('8.a', 8, 'De steun voor handelsbevordering (Aid for Trade) aan ontwikkelingslanden verhogen, in het bijzonder aan de minst ontwikkelde landen, onder meer via het Versterkt Geïntegreerd Kader voor handelsgerelateerde technische bijstand aan de minst ontwikkelde landen', 'Accroître l’appui apporté dans le cadre de l’initiative Aide pour le commerce aux pays en développement, en particulier aux pays les moins avancés, y compris par l’intermédiaire du Cadre intégré renforcé pour l’assistance technique liée au commerce en faveur des pays les moins avancés', 'Increase Aid for Trade support for developing countries, in particular least developed countries, including through the Enhanced Integrated Framework for Trade-related Technical Assistance to Least Developed Countries'),
('8.b', 8, 'Tegen 2020 een wereldwijde strategie voor jongerenwerkgelegenheid ontwikkelen en in werking stellen en het Mondiaal Banenpact van de Internationale Arbeidsorganisatie uitvoeren', 'D’ici à 2020, élaborer et mettre en œuvre une stratégie mondiale en faveur de l’emploi des jeunes et appliquer le Pacte mondial pour l’emploi de l’Organisation internationale du Travail', 'By 2020, develop and operationalize a global strategy for youth employment and implement the Global Jobs Pact of the International Labour Organization'),
('9.1', 9, 'Kwaliteitsvolle, betrouwbare, duurzame en veerkrachtige infrastructuur ontwikkelen, met inbegrip van regionale en grensoverschrijdende infrastructuur, om economische ontwikkeling en menselijk welzijn te ondersteunen, met aandacht voor betaalbare en billijke toegang voor iedereen', 'Mettre en place une infrastructure de qualité, fiable, durable et résiliente, y compris une infrastructure régionale et transfrontière, pour favoriser le développement économique et le bien-être de l’être humain, en privilégiant un accès universel, financièrement abordable et équitable', 'Develop quality, reliable, sustainable and resilient infrastructure, including regional and transborder infrastructure, to support economic development and human well-being, with a focus on affordable and equitable access for all'),
('9.2', 9, 'Inclusieve en duurzame industrialisering bevorderen en tegen 2030 het aandeel van de industrie in de werkgelegenheid en het bruto binnenlands product aanzienlijk verhogen volgens de nationale omstandigheden, en dat aandeel in de minst ontwikkelde landen verdubbelen', 'Promouvoir une industrialisation durable qui profite à tous et, d’ici à 2030, augmenter nettement la contribution de l’industrie à l’emploi et au produit intérieur brut, en fonction du contexte national, et la multiplier par deux dans les pays les moins avancés', 'Promote inclusive and sustainable industrialization and, by 2030, significantly raise industry’s share of employment and gross domestic product, in line with national circumstances, and double its share in least developed countries'),
('9.3', 9, 'De toegang van kleinschalige industriële en andere ondernemingen, in het bijzonder in ontwikkelingslanden, tot financiële diensten, met inbegrip van betaalbaar krediet, en hun integratie in waardeketens en markten verhogen', 'Accroître, en particulier dans les pays en développement, l’accès des entreprises, notamment des petites entreprises industrielles, aux services financiers, y compris aux prêts consentis à des conditions abordables, et leur intégration aux chaînes de valeur et aux marchés', 'Increase the access of small-scale industrial and other enterprises, in particular in developing countries, to financial services, including affordable credit, and their integration into value chains and markets'),
('9.4', 9, 'Tegen 2030 de infrastructuur moderniseren en industrieën aanpassen om ze duurzaam te maken, met een efficiënter gebruik van grondstoffen en een bredere toepassing van schone en milieuvriendelijke technologieën en industriële processen, waarbij alle landen actie ondernemen volgens hun capaciteiten', 'D’ici à 2030, moderniser l’infrastructure et adapter les industries afin de les rendre durables, par une utilisation plus rationnelle des ressources et un recours accru aux technologies et procédés industriels propres et respectueux de l’environnement, chaque pays agissant dans la mesure de ses moyens', 'By 2030, upgrade infrastructure and retrofit industries to make them sustainable, with increased resource-use efficiency and greater adoption of clean and environmentally sound technologies and industrial processes, with all countries taking action in accordance with their respective capabilities'),
('9.5', 9, 'Wetenschappelijk onderzoek versterken en de technologische capaciteiten van industriële sectoren in alle landen, in het bijzonder ontwikkelingslanden, verbeteren, onder meer door tegen 2030 innovatie aan te moedigen en het aantal onderzoekers per miljoen inwoners en de publieke en private uitgaven voor onderzoek en ontwikkeling aanzienlijk te verhogen', 'Renforcer la recherche scientifique, perfectionner les capacités technologiques des secteurs industriels de tous les pays, en particulier des pays en développement, notamment en encourageant l’innovation et en augmentant nettement le nombre de personnes travaillant dans le secteur de la recherche-développement pour 1 million d’habitants et en accroissant les dépenses publiques et privées consacrées à la recherche-développement d’ici à 2030', 'Enhance scientific research, upgrade the technological capabilities of industrial sectors in all countries, in particular developing countries, including, by 2030, encouraging innovation and substantially increasing the number of research and development workers per 1 million people and public and private research and development spending'),
('9.a', 9, 'De ontwikkeling van duurzame en veerkrachtige infrastructuur in ontwikkelingslanden vergemakkelijken via versterkte financiële, technologische en technische steun aan Afrikaanse landen, de minst ontwikkelde landen, ingesloten ontwikkelingslanden en kleine eilandstaten in ontwikkeling', 'Faciliter la mise en place d’une infrastructure durable et résiliente dans les pays en développement en renforçant l’appui financier, technologique et technique apporté aux pays d’Afrique, aux pays les moins avancés, aux pays en développement sans littoral et aux petits États insulaires en développement', 'Facilitate sustainable and resilient infrastructure development in developing countries through enhanced financial, technological and technical support to African countries, least developed countries, landlocked developing countries and small island developing States'),
('9.b', 9, 'Binnenlandse technologieontwikkeling, onderzoek en innovatie in ontwikkelingslanden ondersteunen, onder meer door een gunstige beleidsomgeving te verzekeren voor onder andere industriële diversificatie en meerwaarde op grondstoffen', 'Soutenir les activités de recherche-développement et d’innovation des pays en développement dans le secteur technologique, notamment en instaurant des conditions propices, entre autres, à la diversification industrielle et à l’ajout de valeur aux marchandises', 'Support domestic technology development, research and innovation in developing countries, including by ensuring a conducive policy environment for, inter alia, industrial diversification and value addition to commodities'),
('9.c', 9, 'De toegang tot informatie- en communicatietechnologie aanzienlijk verhogen en ernaar streven tegen 2020 universele en betaalbare toegang tot het internet te bieden in de minst ontwikkelde landen', 'Accroître nettement l’accès aux technologies de l’information et des communications et faire en sorte que tous les habitants des pays les moins avancés aient accès à Internet à un coût abordable d’ici à 2020', 'Significantly increase access to information and communications technology and strive to provide universal and affordable access to the Internet in least developed countries by 2020'),
('10.1', 10, 'Tegen 2030 geleidelijk een inkomensgroei bereiken en behouden voor de onderste 40 procent van de bevolking die hoger ligt dan het nationale gemiddelde', 'D’ici à 2030, assurer progressivement et durablement une croissance des revenus des 40 pour cent de la population les plus pauvres à un rythme plus rapide que le revenu moyen national', 'By 2030, progressively achieve and sustain income growth of the bottom 40 per cent of the population at a rate higher than the national average'),
('10.2', 10, 'Tegen 2030 de sociale, economische en politieke inclusie van iedereen versterken en bevorderen, ongeacht leeftijd, geslacht, handicap, ras, etniciteit, afkomst, religie of economische of andere status', 'D’ici à 2030, autonomiser toutes les personnes et favoriser leur intégration sociale, économique et politique, indépendamment de leur âge, de leur sexe, de leur handicap, de leur race, de leur appartenance ethnique, de leurs origines, de leur religion ou de leur statut économique ou autre', 'By 2030, empower and promote the social, economic and political inclusion of all, irrespective of age, sex, disability, race, ethnicity, origin, religion or economic or other status'),
('10.3', 10, 'Gelijke kansen verzekeren en ongelijke uitkomsten verminderen, onder meer door discriminerende wetten, beleid en praktijken af te schaffen en passende wetgeving, beleid en actie te bevorderen', 'Assurer l’égalité des chances et réduire l’inégalité des résultats, notamment en éliminant les lois, politiques et pratiques discriminatoires et en encourageant l’adoption de lois, politiques et mesures adéquates en la matière', 'Ensure equal opportunity and reduce inequalities of outcome, including by eliminating discriminatory laws, policies and practices and promoting appropriate legislation, policies and action in this regard'),
('10.4', 10, 'Beleid aannemen, in het bijzonder fiscaal, loon- en sociaal beschermingsbeleid, en geleidelijk meer gelijkheid bereiken', 'Adopter des politiques, notamment sur les plans budgétaire, salarial et dans le domaine de la protection sociale, afin de parvenir progressivement à une plus grande égalité', 'Adopt policies, especially fiscal, wage and social protection policies, and progressively achieve greater equality'),
('10.5', 10, 'De regulering en het toezicht op wereldwijde financiële markten en instellingen verbeteren en de uitvoering van die regels versterken', 'Améliorer la réglementation et la surveillance des institutions et marchés financiers mondiaux et renforcer l’application des règles', 'Improve the regulation and monitoring of global financial markets and institutions and strengthen the implementation of such regulations'),
('10.6', 10, 'Een sterkere vertegenwoordiging en inspraak van ontwikkelingslanden verzekeren in de besluitvorming van wereldwijde internationale economische en financiële instellingen, om doeltreffender, geloofwaardiger, verantwoordingsplichtige en legitieme instellingen te krijgen', 'Faire en sorte que les pays en développement soient davantage représentés et entendus lors de la prise de décisions dans les institutions économiques et financières internationales, afin que celles-ci soient plus efficaces, crédibles, transparentes et légitimes', 'Ensure enhanced representation and voice for developing countries in decision-making in global international economic and financial institutions in order to deliver more effective, credible, accountable and legitimate institutions'),
('10.7', 10, 'Ordelijke, veilige, reguliere en verantwoorde migratie en mobiliteit van mensen vergemakkelijken, onder meer via goed gepland en goed beheerd migratiebeleid', 'Faciliter la migration et la mobilité de façon ordonnée, sûre, régulière et responsable, notamment par la mise en œuvre de politiques migratoires planifiées et bien gérées', 'Facilitate orderly, safe, regular and responsible migration and mobility of people, including through the implementation of planned and well-managed migration policies'),
('10.a', 10, 'Het beginsel van speciale en gedifferentieerde behandeling van ontwikkelingslanden, in het bijzonder de minst ontwikkelde landen, toepassen overeenkomstig de akkoorden van de Wereldhandelsorganisatie', 'Mettre en œuvre le principe d’un traitement spécial et différencié pour les pays en développement, en particulier les pays les moins avancés, conformément aux accords de l’Organisation mondiale du commerce', 'Implement the principle of special and differential treatment for developing countries, in particular least developed countries, in accordance with World Trade Organization agreements'),
('10.b', 10, 'Officiële ontwikkelingshulp en financiële stromen, met inbegrip van buitenlandse directe investeringen, aanmoedigen naar staten waar de nood het hoogst is, in het bijzonder de minst ontwikkelde landen, Afrikaanse landen, kleine eilandstaten in ontwikkeling en ingesloten ontwikkelingslanden, overeenkomstig hun nationale plannen en programma''s', 'Stimuler l’aide publique au développement et les flux financiers, y compris les investissements étrangers directs, en faveur des États qui en ont le plus besoin, en particulier les pays les moins avancés, les pays d’Afrique, les petits États insulaires en développement et les pays en développement sans littoral, conformément à leurs plans et programmes nationaux', 'Encourage official development assistance and financial flows, including foreign direct investment, to States where the need is greatest, in particular least developed countries, African countries, small island developing States and landlocked developing countries, in accordance with their national plans and programmes'),
('10.c', 10, 'Tegen 2030 de transactiekosten van geldovermakingen door migranten verlagen tot minder dan 3 procent en overmakingskanalen met kosten hoger dan 5 procent afschaffen', 'D’ici à 2030, faire baisser au-dessous de 3 pour cent les coûts de transaction des envois de fonds effectués par les migrants et éliminer les circuits d’envois de fonds dont les coûts sont supérieurs à 5 pour cent', 'By 2030, reduce to less than 3 per cent the transaction costs of migrant remittances and eliminate remittance corridors with costs higher than 5 per cent'),
('11.1', 11, 'Tegen 2030 toegang verzekeren voor iedereen tot passende, veilige en betaalbare huisvesting en basisdiensten, en sloppenwijken opwaarderen', 'D’ici à 2030, assurer l’accès de tous à un logement et des services de base adéquats et sûrs, à un coût abordable, et assainir les quartiers de taudis', 'By 2030, ensure access for all to adequate, safe and affordable housing and basic services and upgrade slums'),
('11.2', 11, 'Tegen 2030 toegang bieden tot veilige, betaalbare, toegankelijke en duurzame vervoerssystemen voor iedereen en de verkeersveiligheid verbeteren, vooral door het openbaar vervoer uit te breiden, met bijzondere aandacht voor mensen in kwetsbare situaties, vrouwen, kinderen, personen met een handicap en ouderen', 'D’ici à 2030, assurer l’accès de tous à des systèmes de transport sûrs, accessibles et viables, à un coût abordable, en améliorant la sécurité routière, notamment en développant les transports publics, une attention particulière devant être accordée aux besoins des personnes en situation vulnérable, des femmes, des enfants, des personnes handicapées et des personnes âgées', 'By 2030, provide access to safe, affordable, accessible and sustainable transport systems for all, improving road safety, notably by expanding public transport, with special attention to the needs of those in vulnerable situations, women, children, persons with disabilities and older persons'),
('11.3', 11, 'Tegen 2030 inclusieve en duurzame verstedelijking versterken, evenals de capaciteit voor participatieve, geïntegreerde en duurzame planning en beheer van menselijke nederzettingen in alle landen', 'D’ici à 2030, renforcer l’urbanisation durable pour tous et les capacités de planification et de gestion participatives, intégrées et durables des établissements humains dans tous les pays', 'By 2030, enhance inclusive and sustainable urbanization and capacity for participatory, integrated and sustainable human settlement planning and management in all countries'),
('11.4', 11, 'De inspanningen versterken om het culturele en natuurlijke erfgoed van de wereld te beschermen en te vrijwaren', 'Redoubler d’efforts pour protéger et préserver le patrimoine culturel et naturel mondial', 'Strengthen efforts to protect and safeguard the world’s cultural and natural heritage'),
('11.5', 11, 'Tegen 2030 het aantal doden en getroffenen aanzienlijk verminderen en de directe economische verliezen door rampen, met inbegrip van watergerelateerde rampen, ten opzichte van het wereldwijde bruto binnenlands product sterk verlagen, met aandacht voor de bescherming van armen en mensen in kwetsbare situaties', 'D’ici à 2030, réduire nettement le nombre de personnes tuées et le nombre de personnes touchées par les catastrophes, y compris celles qui sont liées à l’eau, et réduire nettement la part du produit intérieur brut mondial représentée par les pertes économiques directement imputables à ces catastrophes, l’accent étant mis sur la protection des pauvres et des personnes en situation vulnérable', 'By 2030, significantly reduce the number of deaths and the number of people affected and substantially decrease the direct economic losses relative to global gross domestic product caused by disasters, including water-related disasters, with a focus on protecting the poor and people in vulnerable situations'),
('11.6', 11, 'Tegen 2030 de nadelige milieu-impact per inwoner van steden verminderen, onder meer met bijzondere aandacht voor luchtkwaliteit en het beheer van huishoudelijk en ander afval', 'D’ici à 2030, réduire l’impact environnemental négatif des villes par habitant, y compris en accordant une attention particulière à la qualité de l’air et à la gestion, notamment municipale, des déchets', 'By 2030, reduce the adverse per capita environmental impact of cities, including by paying special attention to air quality and municipal and other waste management'),
('11.7', 11, 'Tegen 2030 universele toegang bieden tot veilige, inclusieve en toegankelijke, groene en openbare ruimten, in het bijzonder voor vrouwen en kinderen, ouderen en personen met een handicap', 'D’ici à 2030, assurer l’accès de tous, en particulier des femmes et des enfants, des personnes âgées et des personnes handicapées, à des espaces verts et des espaces publics sûrs', 'By 2030, provide universal access to safe, inclusive and accessible, green and public spaces, in particular for women and children, older persons and persons with disabilities'),
('11.a', 11, 'Positieve economische, sociale en ecologische verbanden tussen stedelijke, randstedelijke en landelijke gebieden ondersteunen door de nationale en regionale ontwikkelingsplanning te versterken', 'Favoriser l’établissement de liens économiques, sociaux et environnementaux positifs entre zones urbaines, périurbaines et rurales en renforçant la planification du développement à l’échelle nationale et régionale', 'Support positive economic, social and environmental links between urban, peri-urban and rural areas by strengthening national and regional development planning'),
('11.b', 11, 'Tegen 2020 het aantal steden en nederzettingen aanzienlijk verhogen dat geïntegreerd beleid en plannen aanneemt en uitvoert voor inclusie, efficiënt gebruik van hulpbronnen, mitigatie van en aanpassing aan klimaatverandering en weerbaarheid tegen rampen, en, in lijn met het Sendai-kader voor rampenrisicovermindering 2015–2030, holistisch rampenrisicobeheer op alle niveaus ontwikkelen en uitvoeren', 'D’ici à 2020, accroître nettement le nombre de villes et d’établissements humains qui adoptent et mettent en œuvre des politiques et plans d’action intégrés en faveur de l’insertion de tous, de l’utilisation rationnelle des ressources, de l’adaptation aux effets des changements climatiques et de leur atténuation et de la résilience face aux catastrophes, et élaborer et mettre en œuvre, conformément au Cadre de Sendai pour la réduction des risques de catastrophe (2015‐2030), une gestion globale des risques de catastrophe à tous les niveaux', 'By 2020, substantially increase the number of cities and human settlements adopting and implementing integrated policies and plans towards inclusion, resource efficiency, mitigation and adaptation to climate change, resilience to disasters, and develop and implement, in line with the Sendai Framework for Disaster Risk Reduction 2015–2030, holistic disaster risk management at all levels'),
('11.c', 11, 'De minst ontwikkelde landen ondersteunen, onder meer via financiële en technische bijstand, bij het bouwen van duurzame en veerkrachtige gebouwen met lokale materialen', 'Aider les pays les moins avancés, y compris par une assistance financière et technique, à construire des bâtiments durables et résilients en utilisant des matériaux locaux', 'Support least developed countries, including through financial and technical assistance, in building sustainable and resilient buildings utilizing local materials'),
('12.1', 12, 'Het Tienjarenkader van programma''s voor duurzame consumptie- en productiepatronen uitvoeren, waarbij alle landen actie ondernemen en ontwikkelde landen het voortouw nemen, rekening houdend met de ontwikkeling en capaciteiten van ontwikkelingslanden', 'Mettre en œuvre le Cadre décennal de programmation concernant les modes de consommation et de production durables avec la participation de tous les pays, les pays développés montrant l’exemple en la matière, compte tenu du degré de développement et des capacités des pays en développement', 'Implement the 10‐Year Framework of Programmes on Sustainable Consumption and Production Patterns, all countries taking action, with developed countries taking the lead, taking into account the development and capabilities of developing countries'),
('12.2', 12, 'Tegen 2030 een duurzaam beheer en een efficiënt gebruik van natuurlijke hulpbronnen bereiken', 'D’ici à 2030, parvenir à une gestion durable et à une utilisation rationnelle des ressources naturelles', 'By 2030, achieve the sustainable management and efficient use of natural resources'),
('12.3', 12, 'Tegen 2030 de voedselverspilling per inwoner wereldwijd halveren op het niveau van detailhandel en consumenten en voedselverliezen in productie- en toeleveringsketens verminderen, met inbegrip van verliezen na de oogst', 'D’ici à 2030, réduire de moitié à l’échelle mondiale le volume de déchets alimentaires par habitant, au niveau de la distribution comme de la consommation, et diminuer les pertes de produits alimentaires tout au long des chaînes de production et d’approvisionnement, y compris les pertes après récolte', 'By 2030, halve per capita global food waste at the retail and consumer levels and reduce food losses along production and supply chains, including post-harvest losses'),
('12.4', 12, 'Tegen 2020 een milieuvriendelijk beheer van chemicaliën en alle afval doorheen hun levenscyclus bereiken, volgens de overeengekomen internationale kaders, en hun uitstoot in lucht, water en bodem aanzienlijk verminderen om hun nadelige gevolgen voor de menselijke gezondheid en het milieu te beperken', 'D’ici à 2020, parvenir à une gestion écologiquement rationnelle des produits chimiques et de tous les déchets tout au long de leur cycle de vie, conformément aux principes directeurs arrêtés à l’échelle internationale, et réduire nettement leur déversement dans l’air, l’eau et le sol, afin de minimiser leurs effets négatifs sur la santé et l’environnement', 'By 2020, achieve the environmentally sound management of chemicals and all wastes throughout their life cycle, in accordance with agreed international frameworks, and significantly reduce their release to air, water and soil in order to minimize their adverse impacts on human health and the environment'),
('12.5', 12, 'Tegen 2030 de afvalproductie aanzienlijk verminderen via preventie, vermindering, recyclage en hergebruik', 'D’ici à 2030, réduire nettement la production de déchets par la prévention, la réduction, le recyclage et la réutilisation', 'By 2030, substantially reduce waste generation through prevention, reduction, recycling and reuse'),
('12.6', 12, 'Bedrijven, vooral grote en multinationale bedrijven, aanmoedigen om duurzame praktijken toe te passen en duurzaamheidsinformatie op te nemen in hun rapportering', 'Encourager les entreprises, en particulier les grandes entreprises et les sociétés transnationales, à adopter des pratiques viables et à intégrer dans les rapports qu’elles établissent des informations sur la viabilité', 'Encourage companies, especially large and transnational companies, to adopt sustainable practices and to integrate sustainability information into their reporting cycle'),
('12.7', 12, 'Duurzame overheidsopdrachten bevorderen, overeenkomstig nationaal beleid en nationale prioriteiten', 'Promouvoir des pratiques durables dans le cadre de la passation des marchés publics, conformément aux politiques et priorités nationales', 'Promote public procurement practices that are sustainable, in accordance with national policies and priorities'),
('12.8', 12, 'Tegen 2030 verzekeren dat mensen overal de relevante informatie en het bewustzijn hebben voor duurzame ontwikkeling en levensstijlen in harmonie met de natuur', 'D’ici à 2030, faire en sorte que toutes les personnes, partout dans le monde, aient les informations et connaissances nécessaires au développement durable et à un style de vie en harmonie avec la nature', 'By 2030, ensure that people everywhere have the relevant information and awareness for sustainable development and lifestyles in harmony with nature'),
('12.a', 12, 'Ontwikkelingslanden ondersteunen om hun wetenschappelijke en technologische capaciteit te versterken en naar duurzamere consumptie- en productiepatronen te evolueren', 'Aider les pays en développement à se doter des moyens scientifiques et technologiques qui leur permettent de s’orienter vers des modes de consommation et de production plus durables', 'Support developing countries to strengthen their scientific and technological capacity to move towards more sustainable patterns of consumption and production'),
('12.b', 12, 'Instrumenten ontwikkelen en toepassen om de impact op duurzame ontwikkeling te volgen van duurzaam toerisme dat banen schept en de lokale cultuur en producten promoot', 'Mettre au point et utiliser des outils de contrôle de l’impact sur le développement durable d’un tourisme durable créateur d’emplois et valorisant la culture et les produits locaux', 'Develop and implement tools to monitor sustainable development impacts for sustainable tourism that creates jobs and promotes local culture and products'),
('12.c', 12, 'Inefficiënte subsidies voor fossiele brandstoffen die verspillende consumptie aanmoedigen rationaliseren door marktverstoringen weg te werken, volgens de nationale omstandigheden, onder meer door belastingen te herstructureren en schadelijke subsidies af te bouwen, rekening houdend met de specifieke noden van ontwikkelingslanden en met bescherming van armen en getroffen gemeenschappen', 'Rationaliser les subventions aux combustibles fossiles qui sont source de gaspillage, grâce à l’élimination des distorsions du marché, eu égard au contexte national, y compris au moyen de la restructuration de la fiscalité et de la suppression progressive des subventions préjudiciables qui sont en place, en mettant en évidence leur impact sur l’environnement, en tenant pleinement compte des besoins et de la situation propres aux pays en développement et en réduisant au minimum les éventuels effets négatifs sur le développement de ces pays tout en protégeant les pauvres et les populations concernées', 'Rationalize inefficient fossil-fuel subsidies that encourage wasteful consumption by removing market distortions, in accordance with national circumstances, including by restructuring taxation and phasing out those harmful subsidies, where they exist, to reflect their environmental impacts, taking fully into account the specific needs and conditions of developing countries and minimizing the possible adverse impacts on their development in a manner that protects the poor and the affected communities'),
('13.1', 13, 'De veerkracht en het aanpassingsvermogen aan klimaatgerelateerde gevaren en natuurrampen in alle landen versterken', 'Renforcer, dans tous les pays, la résilience et les capacités d’adaptation face aux aléas climatiques et aux catastrophes naturelles liées au climat', 'Strengthen resilience and adaptive capacity to climate-related hazards and natural disasters in all countries'),
('13.2', 13, 'Maatregelen tegen klimaatverandering integreren in nationaal beleid, nationale strategieën en planning', 'Incorporer des mesures relatives aux changements climatiques dans les politiques, les stratégies et la planification nationales', 'Integrate climate change measures into national policies, strategies and planning'),
('13.3', 13, 'Onderwijs, bewustmaking en de menselijke en institutionele capaciteit verbeteren inzake mitigatie van klimaatverandering, aanpassing, impactvermindering en vroegtijdige waarschuwing', 'Améliorer l’éducation, la sensibilisation et les capacités individuelles et institutionnelles en ce qui concerne l’adaptation aux changements climatiques, l’atténuation de leurs effets et la réduction de leur impact et les systèmes d’alerte rapide', 'Improve education, awareness-raising and human and institutional capacity on climate change mitigation, adaptation, impact reduction and early warning'),
('13.a', 13, 'De verbintenis van de ontwikkelde landen onder het Raamverdrag van de Verenigde Naties inzake klimaatverandering uitvoeren om tegen 2020 jaarlijks samen 100 miljard dollar uit alle bronnen te mobiliseren voor de noden van ontwikkelingslanden, en het Groen Klimaatfonds zo snel mogelijk volledig operationeel maken door het te kapitaliseren', 'Mettre en œuvre l’engagement que les pays développés parties à la Convention-cadre des Nations Unies sur les changements climatiques ont pris de mobiliser ensemble auprès de multiples sources 100 milliards de dollars par an d’ici à 2020 pour répondre aux besoins des pays en développement en ce qui concerne les mesures concrètes d’atténuation et la transparence de leur mise en œuvre et rendre le Fonds vert pour le climat pleinement opérationnel en le dotant dans les plus brefs délais des moyens financiers nécessaires', 'Implement the commitment undertaken by developed-country parties to the United Nations Framework Convention on Climate Change to a goal of mobilizing jointly $100 billion annually by 2020 from all sources to address the needs of developing countries in the context of meaningful mitigation actions and transparency on implementation and fully operationalize the Green Climate Fund through its capitalization as soon as possible'),
('13.b', 13, 'Mechanismen bevorderen om de capaciteit voor doeltreffende klimaatplanning en -beheer te versterken in de minst ontwikkelde landen en kleine eilandstaten in ontwikkeling, met aandacht voor vrouwen, jongeren en lokale en gemarginaliseerde gemeenschappen', 'Promouvoir des mécanismes de renforcement des capacités afin que les pays les moins avancés et les petits États insulaires en développement se dotent de moyens efficaces de planification et de gestion pour faire face aux changements climatiques, l’accent étant mis, notamment, sur les femmes, les jeunes, la population locale et les groupes marginalisés', 'Promote mechanisms for raising capacity for effective climate change-related planning and management in least developed countries and small island developing States, including focusing on women, youth and local and marginalized communities'),
('14.1', 14, 'Tegen 2025 alle vormen van mariene vervuiling voorkomen en aanzienlijk verminderen, in het bijzonder door activiteiten op het land, met inbegrip van zeeafval en nutriëntenvervuiling', 'D’ici à 2025, prévenir et réduire nettement la pollution marine de tous types, en particulier celle résultant des activités terrestres, y compris les déchets en mer et la pollution par les nutriments', 'By 2025, prevent and significantly reduce marine pollution of all kinds, in particular from land-based activities, including marine debris and nutrient pollution'),
('14.2', 14, 'Tegen 2020 mariene en kustecosystemen duurzaam beheren en beschermen om aanzienlijke nadelige gevolgen te vermijden, onder meer door hun veerkracht te versterken, en actie ondernemen voor hun herstel om gezonde en productieve oceanen te bereiken', 'D’ici à 2020, gérer et protéger durablement les écosystèmes marins et côtiers, notamment en renforçant leur résilience, afin d’éviter les graves conséquences de leur dégradation et prendre des mesures en faveur de leur restauration pour rétablir la santé et la productivité des océans', 'By 2020, sustainably manage and protect marine and coastal ecosystems to avoid significant adverse impacts, including by strengthening their resilience, and take action for their restoration in order to achieve healthy and productive oceans'),
('14.3', 14, 'De gevolgen van oceaanverzuring minimaliseren en aanpakken, onder meer via versterkte wetenschappelijke samenwerking op alle niveaus', 'Réduire au maximum l’acidification des océans et lutter contre ses effets, notamment en renforçant la coopération scientifique à tous les niveaux', 'Minimize and address the impacts of ocean acidification, including through enhanced scientific cooperation at all levels'),
('14.4', 14, 'Tegen 2020 de visvangst doeltreffend reguleren en een einde maken aan overbevissing, illegale, niet-gemelde en niet-gereglementeerde visserij en destructieve vispraktijken, en wetenschappelijk onderbouwde beheerplannen uitvoeren om visbestanden zo snel mogelijk te herstellen', 'D’ici à 2020, réglementer efficacement la pêche, mettre un terme à la surpêche, à la pêche illicite, non déclarée et non réglementée et aux pratiques de pêche destructrices et exécuter des plans de gestion fondés sur des données scientifiques, l’objectif étant de rétablir les stocks de poissons le plus rapidement possible, au moins à des niveaux permettant d’obtenir un rendement constant maximal compte tenu des caractéristiques biologiques', 'By 2020, effectively regulate harvesting and end overfishing, illegal, unreported and unregulated fishing and destructive fishing practices and implement science-based management plans, in order to restore fish stocks in the shortest time feasible, at least to levels that can produce maximum sustainable yield as determined by their biological characteristics'),
('14.5', 14, 'Tegen 2020 minstens 10 procent van de kust- en zeegebieden behouden, in overeenstemming met nationaal en internationaal recht en op basis van de beste beschikbare wetenschappelijke informatie', 'D’ici à 2020, préserver au moins 10 pour cent des zones marines et côtières, conformément au droit national et international et compte tenu des meilleures informations scientifiques disponibles', 'By 2020, conserve at least 10 per cent of coastal and marine areas, consistent with national and international law and based on the best available scientific information'),
('14.6', 14, 'Tegen 2020 bepaalde vormen van visserijsubsidies verbieden die bijdragen aan overcapaciteit en overbevissing, subsidies afschaffen die bijdragen aan illegale, niet-gemelde en niet-gereglementeerde visserij en geen nieuwe zulke subsidies invoeren', 'D’ici à 2020, interdire les subventions à la pêche qui contribuent à la surcapacité et à la surpêche, supprimer celles qui favorisent la pêche illicite, non déclarée et non réglementée et s’abstenir d’en accorder de nouvelles, sachant que l’octroi d’un traitement spécial et différencié efficace et approprié aux pays en développement et aux pays les moins avancés doit faire partie intégrante des négociations sur les subventions à la pêche menées dans le cadre de l’Organisation mondiale du commerce', 'By 2020, prohibit certain forms of fisheries subsidies which contribute to overcapacity and overfishing, eliminate subsidies that contribute to illegal, unreported and unregulated fishing and refrain from introducing new such subsidies, recognizing that appropriate and effective special and differential treatment for developing and least developed countries should be an integral part of the World Trade Organization fisheries subsidies negotiation'),
('14.7', 14, 'Tegen 2030 de economische voordelen voor kleine eilandstaten in ontwikkeling en de minst ontwikkelde landen uit het duurzaam gebruik van mariene hulpbronnen verhogen, onder meer via duurzaam beheer van visserij, aquacultuur en toerisme', 'D’ici à 2030, faire bénéficier plus largement les petits États insulaires en développement et les pays les moins avancés des retombées économiques de l’exploitation durable des ressources marines, notamment grâce à une gestion durable des pêches, de l’aquaculture et du tourisme', 'By 2030, increase the economic benefits to small island developing States and least developed countries from the sustainable use of marine resources, including through sustainable management of fisheries, aquaculture and tourism'),
('14.a', 14, 'De wetenschappelijke kennis vergroten, onderzoekscapaciteit ontwikkelen en mariene technologie overdragen om de gezondheid van de oceanen te verbeteren en de bijdrage van mariene biodiversiteit aan de ontwikkeling van ontwikkelingslanden te versterken', 'Approfondir les connaissances scientifiques, renforcer les moyens de recherche et transférer les techniques marines, conformément aux Critères et principes directeurs de la Commission océanographique intergouvernementale concernant le transfert de techniques marines, l’objectif étant d’améliorer la santé des océans et de renforcer la contribution de la biodiversité marine au développement des pays en développement, en particulier des petits États insulaires en développement et des pays les moins avancés', 'Increase scientific knowledge, develop research capacity and transfer marine technology, taking into account the Intergovernmental Oceanographic Commission Criteria and Guidelines on the Transfer of Marine Technology, in order to improve ocean health and to enhance the contribution of marine biodiversity to the development of developing countries, in particular small island developing States and least developed countries'),
('14.b', 14, 'Kleinschalige ambachtelijke vissers toegang bieden tot mariene hulpbronnen en markten', 'Garantir aux petits pêcheurs l’accès aux ressources marines et aux marchés', 'Provide access for small-scale artisanal fishers to marine resources and markets'),
('14.c', 14, 'Het behoud en duurzaam gebruik van oceanen en hun hulpbronnen versterken door het internationaal recht toe te passen zoals weergegeven in het VN-Zeerechtverdrag', 'Améliorer la conservation et l’utilisation durable des océans et de leurs ressources en application des dispositions du droit international, énoncées dans la Convention des Nations Unies sur le droit de la mer, qui fournit le cadre juridique requis pour la conservation et l’utilisation durable des océans et de leurs ressources, comme il est rappelé au paragraphe 158 de « L’avenir que nous voulons »', 'Enhance the conservation and sustainable use of oceans and their resources by implementing international law as reflected in the United Nations Convention on the Law of the Sea, which provides the legal framework for the conservation and sustainable use of oceans and their resources, as recalled in paragraph 158 of “The future we want”'),
('15.1', 15, 'Tegen 2020 het behoud, het herstel en het duurzaam gebruik verzekeren van landecosystemen en zoetwaterecosystemen in het binnenland en hun diensten, in het bijzonder bossen, wetlands, bergen en droge gebieden, volgens de verplichtingen uit internationale akkoorden', 'D’ici à 2020, garantir la préservation, la restauration et l’exploitation durable des écosystèmes terrestres et des écosystèmes d’eau douce et des services connexes, en particulier des forêts, des zones humides, des montagnes et des zones arides, conformément aux obligations découlant des accords internationaux', 'By 2020, ensure the conservation, restoration and sustainable use of terrestrial and inland freshwater ecosystems and their services, in particular forests, wetlands, mountains and drylands, in line with obligations under international agreements'),
('15.2', 15, 'Tegen 2020 duurzaam beheer van alle soorten bossen bevorderen, ontbossing stoppen, aangetaste bossen herstellen en bebossing en herbebossing wereldwijd aanzienlijk verhogen', 'D’ici à 2020, promouvoir la gestion durable de tous les types de forêt, mettre un terme à la déforestation, restaurer les forêts dégradées et accroître nettement le boisement et le reboisement au niveau mondial', 'By 2020, promote the implementation of sustainable management of all types of forests, halt deforestation, restore degraded forests and substantially increase afforestation and reforestation globally'),
('15.3', 15, 'Tegen 2030 woestijnvorming bestrijden, aangetast land en aangetaste bodem herstellen, met inbegrip van land getroffen door woestijnvorming, droogte en overstromingen, en streven naar een wereld zonder netto bodemdegradatie', 'D’ici à 2030, lutter contre la désertification, restaurer les terres et sols dégradés, notamment les terres touchées par la désertification, la sécheresse et les inondations, et s’efforcer de parvenir à un monde sans dégradation des terres', 'By 2030, combat desertification, restore degraded land and soil, including land affected by desertification, drought and floods, and strive to achieve a land degradation-neutral world'),
('15.4', 15, 'Tegen 2030 het behoud van bergecosystemen verzekeren, met inbegrip van hun biodiversiteit, om hun vermogen te versterken voordelen te bieden die essentieel zijn voor duurzame ontwikkeling', 'D’ici à 2030, assurer la préservation des écosystèmes montagneux, notamment de leur biodiversité, afin de mieux tirer parti de leurs bienfaits essentiels pour le développement durable', 'By 2030, ensure the conservation of mountain ecosystems, including their biodiversity, in order to enhance their capacity to provide benefits that are essential for sustainable development'),
('15.5', 15, 'Dringend en aanzienlijk actie ondernemen om de aantasting van natuurlijke habitats te verminderen, het verlies aan biodiversiteit te stoppen en tegen 2020 bedreigde soorten te beschermen en hun uitsterven te voorkomen', 'Prendre d’urgence des mesures énergiques pour réduire la dégradation du milieu naturel, mettre un terme à l’appauvrissement de la biodiversité et, d’ici à 2020, protéger les espèces menacées et prévenir leur extinction', 'Take urgent and significant action to reduce the degradation of natural habitats, halt the loss of biodiversity and, by 2020, protect and prevent the extinction of threatened species'),
('15.6', 15, 'Een eerlijke en billijke verdeling bevorderen van de voordelen uit het gebruik van genetische hulpbronnen en passende toegang tot die hulpbronnen bevorderen, zoals internationaal overeengekomen', 'Favoriser le partage juste et équitable des bénéfices découlant de l’utilisation des ressources génétiques et promouvoir un accès approprié à celles-ci, ainsi que cela a été décidé à l’échelle internationale', 'Promote fair and equitable sharing of the benefits arising from the utilization of genetic resources and promote appropriate access to such resources, as internationally agreed'),
('15.7', 15, 'Dringend actie ondernemen om een einde te maken aan stroperij en handel in beschermde planten- en diersoorten en zowel de vraag naar als het aanbod van illegale wildproducten aanpakken', 'Prendre d’urgence des mesures pour mettre un terme au braconnage et au trafic d’espèces végétales et animales protégées et s’attaquer au problème sous l’angle de l’offre et de la demande', 'Take urgent action to end poaching and trafficking of protected species of flora and fauna and address both demand and supply of illegal wildlife products'),
('15.8', 15, 'Tegen 2020 maatregelen invoeren om de introductie van invasieve uitheemse soorten te voorkomen en hun impact op land- en waterecosystemen aanzienlijk te verminderen, en de prioritaire soorten beheersen of uitroeien', 'D’ici à 2020, prendre des mesures pour empêcher l’introduction d’espèces exotiques envahissantes, atténuer sensiblement les effets que ces espèces ont sur les écosystèmes terrestres et aquatiques et contrôler ou éradiquer les espèces prioritaires', 'By 2020, introduce measures to prevent the introduction and significantly reduce the impact of invasive alien species on land and water ecosystems and control or eradicate the priority species'),
('15.9', 15, 'Tegen 2020 de waarden van ecosystemen en biodiversiteit integreren in nationale en lokale planning, ontwikkelingsprocessen, armoedebestrijdingsstrategieën en rekeningen', 'D’ici à 2020, intégrer la protection des écosystèmes et de la biodiversité dans la planification nationale, dans les mécanismes de développement, dans les stratégies de réduction de la pauvreté et dans la comptabilité', 'By 2020, integrate ecosystem and biodiversity values into national and local planning, development processes, poverty reduction strategies and accounts'),
('15.a', 15, 'Financiële middelen uit alle bronnen mobiliseren en aanzienlijk verhogen om biodiversiteit en ecosystemen te behouden en duurzaam te gebruiken', 'Mobiliser des ressources financières de toutes provenances et les augmenter nettement pour préserver la biodiversité et les écosystèmes et les exploiter durablement', 'Mobilize and significantly increase financial resources from all sources to conserve and sustainably use biodiversity and ecosystems'),
('15.b', 15, 'Aanzienlijke middelen uit alle bronnen en op alle niveaus mobiliseren om duurzaam bosbeheer te financieren en ontwikkelingslanden passende stimulansen te bieden om dat beheer te bevorderen, onder meer voor behoud en herbebossing', 'Mobiliser d’importantes ressources de toutes provenances et à tous les niveaux pour financer la gestion durable des forêts et inciter les pays en développement à privilégier ce type de gestion, notamment aux fins de la préservation des forêts et du reboisement', 'Mobilize significant resources from all sources and at all levels to finance sustainable forest management and provide adequate incentives to developing countries to advance such management, including for conservation and reforestation'),
('15.c', 15, 'De wereldwijde steun versterken voor de strijd tegen stroperij en handel in beschermde soorten, onder meer door de capaciteit van lokale gemeenschappen te vergroten om duurzame bestaansmiddelen te ontwikkelen', 'Apporter, à l’échelon mondial, un soutien accru à l’action menée pour lutter contre le braconnage et le trafic d’espèces protégées, notamment en donnant aux populations locales d’autres moyens d’assurer durablement leur subsistance', 'Enhance global support for efforts to combat poaching and trafficking of protected species, including by increasing the capacity of local communities to pursue sustainable livelihood opportunities'),
('16.1', 16, 'Alle vormen van geweld en de daarmee samenhangende sterftecijfers overal aanzienlijk verminderen', 'Réduire nettement, partout dans le monde, toutes les formes de violence et les taux de mortalité qui y sont associés', 'Significantly reduce all forms of violence and related death rates everywhere'),
('16.2', 16, 'Een einde maken aan misbruik, uitbuiting, mensenhandel en alle vormen van geweld tegen en foltering van kinderen', 'Mettre un terme à la maltraitance, à l’exploitation et à la traite, et à toutes les formes de violence et de torture dont sont victimes les enfants', 'End abuse, exploitation, trafficking and all forms of violence against and torture of children'),
('16.3', 16, 'De rechtsstaat bevorderen op nationaal en internationaal niveau en gelijke toegang tot justitie voor iedereen verzekeren', 'Promouvoir l’état de droit dans l’ordre interne et international et garantir à tous un égal accès à la justice', 'Promote the rule of law at the national and international levels and ensure equal access to justice for all'),
('16.4', 16, 'Tegen 2030 illegale financiële en wapenstromen aanzienlijk verminderen, de recuperatie en teruggave van gestolen vermogen versterken en alle vormen van georganiseerde misdaad bestrijden', 'D’ici à 2030, réduire nettement les flux financiers illicites et le trafic d’armes, renforcer les activités de récupération et de restitution des biens volés et lutter contre toutes les formes de criminalité organisée', 'By 2030, significantly reduce illicit financial and arms flows, strengthen the recovery and return of stolen assets and combat all forms of organized crime'),
('16.5', 16, 'Corruptie en omkoping in al hun vormen aanzienlijk verminderen', 'Réduire nettement la corruption et la pratique des pots-de-vin sous toutes leurs formes', 'Substantially reduce corruption and bribery in all their forms'),
('16.6', 16, 'Doeltreffende, verantwoordingsplichtige en transparante instellingen op alle niveaus uitbouwen', 'Mettre en place des institutions efficaces, responsables et transparentes à tous les niveaux', 'Develop effective, accountable and transparent institutions at all levels'),
('16.7', 16, 'Een responsieve, inclusieve, participatieve en representatieve besluitvorming op alle niveaus verzekeren', 'Faire en sorte que le dynamisme, l’ouverture, la participation et la représentation à tous les niveaux caractérisent la prise de décisions', 'Ensure responsive, inclusive, participatory and representative decision-making at all levels'),
('16.8', 16, 'De deelname van ontwikkelingslanden aan de instellingen van wereldwijd bestuur verbreden en versterken', 'Élargir et renforcer la participation des pays en développement aux institutions chargées de la gouvernance au niveau mondial', 'Broaden and strengthen the participation of developing countries in the institutions of global governance'),
('16.9', 16, 'Tegen 2030 een wettelijke identiteit voor iedereen bieden, met inbegrip van geboorteregistratie', 'D’ici à 2030, garantir à tous une identité juridique, notamment grâce à l’enregistrement des naissances', 'By 2030, provide legal identity for all, including birth registration'),
('16.10', 16, 'Openbare toegang tot informatie verzekeren en fundamentele vrijheden beschermen, overeenkomstig nationale wetgeving en internationale akkoorden', 'Garantir l’accès public à l’information et protéger les libertés fondamentales, conformément à la législation nationale et aux accords internationaux', 'Ensure public access to information and protect fundamental freedoms, in accordance with national legislation and international agreements'),
('16.a', 16, 'Relevante nationale instellingen versterken, onder meer via internationale samenwerking, voor capaciteitsopbouw op alle niveaus, in het bijzonder in ontwikkelingslanden, om geweld te voorkomen en terrorisme en misdaad te bestrijden', 'Appuyer, notamment dans le cadre de la coopération internationale, les institutions nationales chargées de renforcer, à tous les niveaux, les moyens de prévenir la violence et de lutter contre le terrorisme et la criminalité, en particulier dans les pays en développement', 'Strengthen relevant national institutions, including through international cooperation, for building capacity at all levels, in particular in developing countries, to prevent violence and combat terrorism and crime'),
('16.b', 16, 'Niet-discriminerende wetten en beleid voor duurzame ontwikkeling bevorderen en handhaven', 'Promouvoir et appliquer des lois et politiques non discriminatoires pour le développement durable', 'Promote and enforce non-discriminatory laws and policies for sustainable development'),
('17.1', 17, 'De mobilisatie van binnenlandse middelen versterken, onder meer via internationale steun aan ontwikkelingslanden, om de binnenlandse capaciteit voor het innen van belastingen en andere inkomsten te verbeteren', 'Améliorer, notamment grâce à l’aide internationale aux pays en développement, la mobilisation de ressources nationales en vue de renforcer les capacités nationales de collecte de l’impôt et d’autres recettes', 'Strengthen domestic resource mobilization, including through international support to developing countries, to improve domestic capacity for tax and other revenue collection'),
('17.2', 17, 'Ontwikkelde landen voeren hun verbintenissen inzake officiële ontwikkelingshulp volledig uit, met inbegrip van de verbintenis van veel ontwikkelde landen om 0,7 procent van het bruto nationaal inkomen aan ontwikkelingshulp te besteden en 0,15 tot 0,20 procent aan de minst ontwikkelde landen', 'Faire en sorte que les pays développés honorent tous leurs engagements en matière d’aide publique au développement, notamment celui pris par nombre d’entre eux de consacrer 0,7 pour cent de leur revenu national brut à l’aide aux pays en développement et entre 0,15 pour cent et 0,20 pour cent à l’aide aux pays les moins avancés, les bailleurs de fonds étant encouragés à envisager de se fixer pour objectif de consacrer au moins 0,20 pour cent de leur revenu national brut à l’aide aux pays les moins avancés', 'Developed countries to implement fully their official development assistance commitments, including the commitment by many developed countries to achieve the target of 0.7 per cent of gross national income for official development assistance (ODA/GNI) to developing countries and 0.15 to 0.20 per cent of ODA/GNI to least developed countries; ODA providers are encouraged to consider setting a target to provide at least 0.20 per cent of ODA/GNI to least developed countries'),
('17.3', 17, 'Bijkomende financiële middelen uit meerdere bronnen mobiliseren voor ontwikkelingslanden', 'Mobiliser des ressources financières supplémentaires de diverses provenances en faveur des pays en développement', 'Mobilize additional financial resources for developing countries from multiple sources'),
('17.4', 17, 'Ontwikkelingslanden helpen schulden op lange termijn houdbaar te maken via gecoördineerd beleid voor schuldfinanciering, schuldverlichting en schuldherschikking, en de buitenlandse schuld van zwaar verschuldigde arme landen aanpakken', 'Aider les pays en développement à assurer la viabilité à long terme de leur dette au moyen de politiques concertées visant à favoriser le financement de la dette, son allégement ou sa restructuration, selon le cas, et réduire le surendettement en réglant le problème de la dette extérieure des pays pauvres très endettés', 'Assist developing countries in attaining long-term debt sustainability through coordinated policies aimed at fostering debt financing, debt relief and debt restructuring, as appropriate, and address the external debt of highly indebted poor countries to reduce debt distress'),
('17.5', 17, 'Investeringsbevorderende regelingen voor de minst ontwikkelde landen aannemen en uitvoeren', 'Adopter et mettre en œuvre des dispositifs visant à encourager l’investissement en faveur des pays les moins avancés', 'Adopt and implement investment promotion regimes for least developed countries'),
('17.6', 17, 'De noord-zuid-, zuid-zuid- en driehoekssamenwerking inzake en de toegang tot wetenschap, technologie en innovatie versterken en kennisdeling op wederzijds overeengekomen voorwaarden verbeteren, onder meer via betere coördinatie tussen bestaande mechanismen en een wereldwijd mechanisme voor technologiefacilitering', 'Renforcer l’accès à la science, à la technologie et à l’innovation et la coopération Nord-Sud et Sud-Sud et la coopération triangulaire régionale et internationale dans ces domaines et améliorer le partage des savoirs selon des modalités arrêtées d’un commun accord, notamment en coordonnant mieux les mécanismes existants, en particulier au niveau des organismes des Nations Unies, et dans le cadre d’un mécanisme mondial de facilitation des technologies', 'Enhance North-South, South-South and triangular regional and international cooperation on and access to science, technology and innovation and enhance knowledge-sharing on mutually agreed terms, including through improved coordination among existing mechanisms, in particular at the United Nations level, and through a global technology facilitation mechanism'),
('17.7', 17, 'De ontwikkeling, overdracht en verspreiding van milieuvriendelijke technologieën naar ontwikkelingslanden bevorderen op gunstige voorwaarden, zoals wederzijds overeengekomen', 'Promouvoir la mise au point, le transfert et la diffusion de technologies respectueuses de l’environnement en faveur des pays en développement, à des conditions favorables, y compris privilégiées et préférentielles, arrêtées d’un commun accord', 'Promote the development, transfer, dissemination and diffusion of environmentally sound technologies to developing countries on favourable terms, including on concessional and preferential terms, as mutually agreed'),
('17.8', 17, 'De technologiebank en het mechanisme voor capaciteitsopbouw inzake wetenschap, technologie en innovatie voor de minst ontwikkelde landen tegen 2017 volledig operationeel maken en het gebruik van ondersteunende technologie, in het bijzonder ICT, verbeteren', 'Faire en sorte que la banque de technologies et le mécanisme de renforcement des capacités scientifiques et technologiques et des capacités d’innovation des pays les moins avancés soient pleinement opérationnels d’ici à 2017 et renforcer l’utilisation des technologies clefs, en particulier de l’informatique et des communications', 'Fully operationalize the technology bank and science, technology and innovation capacity-building mechanism for least developed countries by 2017 and enhance the use of enabling technology, in particular information and communications technology'),
('17.9', 17, 'De internationale steun versterken voor doeltreffende en gerichte capaciteitsopbouw in ontwikkelingslanden om nationale plannen voor de uitvoering van alle duurzameontwikkelingsdoelen te ondersteunen', 'Apporter, à l’échelon international, un soutien accru pour assurer le renforcement efficace et ciblé des capacités des pays en développement et appuyer ainsi les plans nationaux visant à atteindre tous les objectifs de développement durable, notamment dans le cadre de la coopération Nord-Sud et Sud-Sud et de la coopération triangulaire', 'Enhance international support for implementing effective and targeted capacity-building in developing countries to support national plans to implement all the Sustainable Development Goals, including through North-South, South-South and triangular cooperation'),
('17.10', 17, 'Een universeel, regelgebaseerd, open, niet-discriminerend en billijk multilateraal handelssysteem onder de Wereldhandelsorganisatie bevorderen, onder meer door de onderhandelingen van de Doha-ontwikkelingsagenda af te ronden', 'Promouvoir un système commercial multilatéral universel, réglementé, ouvert, non discriminatoire et équitable sous l’égide de l’Organisation mondiale du commerce, notamment grâce à la tenue de négociations dans le cadre du Programme de Doha pour le développement', 'Promote a universal, rules-based, open, non‐discriminatory and equitable multilateral trading system under the World Trade Organization, including through the conclusion of negotiations under its Doha Development Agenda'),
('17.11', 17, 'De export van ontwikkelingslanden aanzienlijk verhogen, met het oog op een verdubbeling van het aandeel van de minst ontwikkelde landen in de wereldexport tegen 2020', 'Accroître nettement les exportations des pays en développement, en particulier en vue de doubler la part des pays les moins avancés dans les exportations mondiales d’ici à 2020', 'Significantly increase the exports of developing countries, in particular with a view to doubling the least developed countries’ share of global exports by 2020'),
('17.12', 17, 'Tijdig en duurzaam markttoegang zonder rechten en quota verlenen aan alle minst ontwikkelde landen, overeenkomstig de besluiten van de Wereldhandelsorganisatie, onder meer met transparante en eenvoudige preferentiële oorsprongsregels', 'Permettre l’accès rapide de tous les pays les moins avancés aux marchés en franchise de droits et sans contingent, conformément aux décisions de l’Organisation mondiale du commerce, notamment en veillant à ce que les règles préférentielles applicables aux importations provenant des pays les moins avancés soient transparentes et simples et facilitent l’accès aux marchés', 'Realize timely implementation of duty-free and quota-free market access on a lasting basis for all least developed countries, consistent with World Trade Organization decisions, including by ensuring that preferential rules of origin applicable to imports from least developed countries are transparent and simple, and contribute to facilitating market access'),
('17.13', 17, 'De wereldwijde macro-economische stabiliteit versterken, onder meer via beleidscoördinatie en beleidscoherentie', 'Renforcer la stabilité macroéconomique mondiale, notamment en favorisant la coordination et la cohérence des politiques', 'Enhance global macroeconomic stability, including through policy coordination and policy coherence'),
('17.14', 17, 'De beleidscoherentie voor duurzame ontwikkeling versterken', 'Renforcer la cohérence des politiques de développement durable', 'Enhance policy coherence for sustainable development'),
('17.15', 17, 'De beleidsruimte en het leiderschap van elk land respecteren om beleid voor armoedebestrijding en duurzame ontwikkeling op te stellen en uit te voeren', 'Respecter la marge de manœuvre et l’autorité de chaque pays en ce qui concerne l’élaboration et l’application des politiques d’élimination de la pauvreté et de développement durable', 'Respect each country’s policy space and leadership to establish and implement policies for poverty eradication and sustainable development'),
('17.16', 17, 'Het wereldwijd partnerschap voor duurzame ontwikkeling versterken, aangevuld met partnerschappen tussen meerdere belanghebbenden die kennis, expertise, technologie en financiële middelen mobiliseren en delen, om de duurzameontwikkelingsdoelen in alle landen te helpen bereiken', 'Renforcer le Partenariat mondial pour le développement durable, associé à des partenariats multipartites permettant de mobiliser et de partager des savoirs, des connaissances spécialisées, des technologies et des ressources financières, afin d’aider tous les pays, en particulier les pays en développement, atteindre les objectifs de développement durable', 'Enhance the Global Partnership for Sustainable Development, complemented by multi-stakeholder partnerships that mobilize and share knowledge, expertise, technology and financial resources, to support the achievement of the Sustainable Development Goals in all countries, in particular developing countries'),
('17.17', 17, 'Doeltreffende publieke, publiek-private en maatschappelijke partnerschappen aanmoedigen en bevorderen, voortbouwend op de ervaring en financieringsstrategieën van partnerschappen', 'Encourager et promouvoir les partenariats publics, les partenariats public-privé et les partenariats avec la société civile, en faisant fond sur l’expérience acquise et les stratégies de financement appliquées en la matière', 'Encourage and promote effective public, public-private and civil society partnerships, building on the experience and resourcing strategies of partnerships'),
('17.18', 17, 'Tegen 2020 de steun voor capaciteitsopbouw aan ontwikkelingslanden versterken om de beschikbaarheid van kwaliteitsvolle, tijdige en betrouwbare gegevens, opgesplitst naar inkomen, geslacht, leeftijd, ras, etniciteit, migratiestatus, handicap, geografische locatie en andere relevante kenmerken, aanzienlijk te verhogen', 'D’ici à 2020, apporter un soutien accru au renforcement des capacités des pays en développement, notamment des pays les moins avancés et des petits États insulaires en développement, l’objectif étant de disposer d’un beaucoup plus grand nombre de données de qualité, actualisées et exactes, ventilées par niveau de revenu, sexe, âge, race, appartenance ethnique, statut migratoire, handicap et emplacement géographique, et selon d’autres caractéristiques propres à chaque pays', 'By 2020, enhance capacity-building support to developing countries, including for least developed countries and small island developing States, to increase significantly the availability of high-quality, timely and reliable data disaggregated by income, gender, age, race, ethnicity, migratory status, disability, geographic location and other characteristics relevant in national contexts'),
('17.19', 17, 'Tegen 2030 voortbouwen op bestaande initiatieven om maatstaven voor vooruitgang inzake duurzame ontwikkeling te ontwikkelen die het bruto binnenlands product aanvullen, en de statistische capaciteitsopbouw in ontwikkelingslanden ondersteunen', 'D’ici à 2030, tirer parti des initiatives existantes pour établir des indicateurs de progrès en matière de développement durable qui viendraient compléter le produit intérieur brut, et appuyer le renforcement des capacités statistiques des pays en développement', 'By 2030, build on existing initiatives to develop measurements of progress on sustainable development that complement gross domestic product, and support statistical capacity-building in developing countries')
) v(code, goal, title_nl, title_fr, title_en);

-- Members read the reference through one call; it never changes at runtime.
create function public.sdg_reference() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'n', g.n, 'short_nl', g.short_nl, 'short_fr', g.short_fr, 'short_en', g.short_en,
      'title_nl', g.title_nl, 'title_fr', g.title_fr, 'title_en', g.title_en,
      'targets', (select jsonb_agg(jsonb_build_object('code', t.code, 'title_nl', t.title_nl,
                    'title_fr', t.title_fr, 'title_en', t.title_en, 'nl_working', t.nl_working)
                  order by t.sort)
                  from public.sdg_targets t where t.goal = g.n))
    order by g.n), '[]'::jsonb)
  from public.sdg_goals g
  where public.is_member();
$$;
revoke execute on function public.sdg_reference() from public, anon;
grant execute on function public.sdg_reference() to authenticated;
`;export{e as default};